/**
 * In-app help as a navigable guide: a home page (Start here, search, topic tiles grouped by area) and one page
 * per topic with headed sections and Previous / Next. Search matches every section and opens the topic at it.
 * Written for someone holding the radio for the first time; keep it in step with the screens.
 */
public class HelpView extends LinearLayout {

    static final class Section { final String head, text; Section(String h, String t) { head = h; text = t; } }
    static final class Topic {
        final String icon, title, summary, group; final int accent; final Section[] sections;
        Topic(String group, String icon, int accent, String title, String summary, Section... s) { this.group = group; this.icon = icon; this.accent = accent; this.title = title; this.summary = summary; sections = s; }
    }
    private static Section s(String h, String t) { return new Section(h, t); }
    /** The guide for SignalDeck Web: per topic {group, title, summary, heading 1, text 1, heading 2, text 2, …}. */
    public static java.util.List<String[]> topicsForWeb() {
        java.util.List<String[]> out = new java.util.ArrayList<>();
        for (Topic t : TOPICS) {
            String[] r = new String[3 + 2 * t.sections.length]; r[0] = t.group; r[1] = t.title; r[2] = t.summary;
            for (int i = 0; i < t.sections.length; i++) { r[3 + 2 * i] = t.sections[i].head; r[4 + 2 * i] = t.sections[i].text; }
            out.add(r);
        }
        return out;
    }

    static final Topic[] TOPICS = {
        new Topic("Start here", "radio", Neo.CYAN, "Getting started", "Take over the radio, pick a channel, talk.",
            s("1  Take over the radio", "This app and the stock walkie-talkie app cannot share the radio. Open Device and tap Take over: the stock app is paused and its icon hidden until you tap Hand back. The app needs Magisk root to reach the radio's serial port; allow it when Magisk asks. If taking over fails partway, the stock app is switched back on, so the phone is never left without a working radio app."),
            s("2  Pick a channel", "On the Intercom page the round arrows step through your channels. Or open Channels and tap a card, then Use. The first time (and whenever the list is empty when SignalDeck takes the radio) it asks whether to import your channels from the stock app; Start empty skips it and is remembered. Channels can be edited, added, backed up and restored."),
            s("3  Talk and listen", "Hold the large round key, or the phone's side PTT button, to talk; release it to listen. The key is amber when idle, green while the radio hears someone and red while you transmit. SignalDeck ends a transmission at the transmit limit (Device \u2192 Longest transmission, 2 minutes unless you change it); past 30 seconds the heat guard also applies (Good to know \u2192 Transmitting legally \u2192 Time limit)."),
            s("The launch screen", "When SignalDeck opens it shows its launch screen for about two and a half seconds, with the version number near the bottom, while the radio comes up behind it. Tap it to skip. Going back to the app while it is still open (launcher icon, recent apps, a notification) never shows it again; it plays only after the app was closed."),
            s("4  Hear more", "Turn on SOFT SQ to hear weaker stations without static, TXT to read live captions of what is said, and SCAN to search the channels of a zone for activity. Each has its own topic in this guide.")),

        new Topic("On the intercom", "intercom", Neo.CYAN, "Intercom", "The main page: channel, talk key, activity.",
            s("Channel", "The big number is the current channel and the title above it is its name. The round arrows step to the previous or next channel of the current zone. On NOAA weather, marine and railroad channels the talk key is dimmed: those frequencies are receive-only."),
            s("Talkgroup", "On a DMR channel the CALL cell under the frequencies shows who you transmit to. Long-press it to pick another talkgroup without editing the channel (a plain tap does nothing, so it cannot change by accident). The list starts with the channel's programmed call, then your group contacts (Contacts page, type Group). After a pick the radio transmits group calls to that talkgroup and hears it (it is added to the receive list for the time being), the cell turns amber and reads CALL · PICKED, and the channel itself is not changed. It lasts until you change channel, scan to another one or use the VFO; pick the programmed entry to go back. Not while transmitting."),
            s("Talk key", "Hold to transmit, release to listen. Amber: idle. Green: the radio is receiving. Red: transmitting. The phone's side PTT button and, if you switch them on in Device, the volume-up key and a custom PTT key you taught it do the same."),
            s("Activity panel", "The panel says what is happening (ready, receiving, transmitting, who called) and lists the last events on this channel; the bars are the spectrum of what is heard, low notes on the left and high on the right (200 Hz to 3.6 kHz), and fall back to silence when nothing is heard. SignalDeck Web draws the same bars on its Intercom page. Tap the panel for Last heard. At the top, Alerts lists the warnings and refusals of the last 7 days (for example Android Auto dropping while you talk, a transmission refused on a receive-only or DMR channel, channel busy, keyword alerts), and Car and coverage lists Android Auto and coverage events. Tap one for what it means and what to do, with every line logged within 20 seconds of it, and a button to tune its channel. Below that is everyone and every channel with activity, newest first, with names from your contacts and the RadioID list, plus the recordings player and the caption transcript; tap a heard line to switch to that channel. The small cross on the panel clears its list and hides it until the next reception or transmission; the small button left in its corner brings it back at once. Last heard keeps everything."),
            s("Activity statistics", "Last heard \u2192 Activity counts what the radio received today, in the last 7 or 30 days: receptions and minutes of audio per channel, busiest first, and a bar for each hour of the day with the busiest hour in amber. Tap a channel to tune it. Make a scan zone of the busiest puts the twelve busiest channels into a zone called Busiest channels and selects it, so SCAN searches where the activity is."),
            s("Tone offer", "When a CTCSS tone is heard on an analog channel that has none set, the panel says so. Tap it to make that tone the channel's receive and transmit tone."),
            s("Signal", "The classic page shows the signal strength in dBm in the yellow box. The new look shows a segmented S-meter: S1 to S9 in cyan, then amber and red above S9 (+20, +40), with the S-unit and dBm beside it. When nothing is being received the meter is dark and says NO SIGNAL, with the noise floor the radio reads beside it."),
            s("Two looks", "Device → Radio settings → New intercom look switches between the redesigned page (the default) and the classic one. The new page's menu button and a long-press on the classic page's title switch too. Both have the same controls."),
            s("Small screens", "On a phone whose screen is less than 700 dp tall (for example a 480 × 854 handheld), the new page is drawn smaller so everything fits above the tab bar: the channel number, its arrows and the FM/UHF/power chips move inside the readout card, text and buttons are smaller, the talk key is 132 dp and the six buttons are 66 × 44 dp in their usual places, and the tab bar is lower. It is the same page with the same controls, only smaller. Device → Radio settings → Intercom layout sets it: Automatic (the default, chosen by the screen height, which it shows), Regular or Compact. Changing it rebuilds the screen."),
            s("Music, calls and the car", "While something is heard, the radio asks Android for the audio: music and podcasts dip under it and come back 2.5 seconds after the transmission ends. In Android Auto this is what sends the radio to the car speakers: the car plays it like a navigation prompt, turning its music down meanwhile, and the car's navigation volume sets its loudness. When Android Auto starts it takes the audio for a moment; the radio takes it back within a few seconds.")),

        new Topic("On the intercom", "scan", Neo.CYAN, "Scanning and zones", "SCAN searches a zone; ZONE picks one.",
            s("Scan", "SCAN steps through the channels of the current zone, about one and a half seconds each (two and a half on phones whose radio reports a reception later, such as the Blackview Xplore 1), and stops on a channel with activity. It moves on about two and a half seconds after the activity ends. Tap SCAN again to stop."),
            s("Skip a channel", "Long-press SCAN while it is holding on a channel to leave that channel out for the rest of this scan."),
            s("Priority channel", "In Channels, tap a channel and Make scan priority. While scanning, that channel (even one outside the zone) is checked again after every three other channels and the scan stops there when it is busy, so you do not miss it. While the scan is held on another busy channel, it still checks the priority channel every 10 seconds (a short gap in the audio) and moves to it if it is busy. Its card shows PRIORITY; the same button clears it."),
            s("Soft SQ while scanning", "While scanning, Soft SQ is used on every analog channel, so weak stations are caught and static is not. Each channel keeps its own Soft SQ level, set with the slider or in Channels → Edit; a channel that was never set uses 5, the middle of 1 (lenient) to 9 (strict). The level is applied on every step of the scan, not fixed when the scan starts. A channel with a receive tone (CTCSS) opens on its tone instead. Moving the slider while the scan is held on a channel changes that channel's level. A channel that only had Soft SQ for the scan returns to its own squelch when the scan stops. Turn this off in Device → Radio settings to scan with the radio's own squelch."),
            s("Zones", "ZONE opens the zone list: tap a zone to make the arrows, the scanner and the car's channel list use only its channels, or ALL channels for every one. Each zone remembers the channel you last used in it, and choosing the zone tunes that channel (the first time, the radio stays where it is if the channel is in the zone, else it takes the zone's first channel); while you talk, scan or use the VFO the channel is left alone. Starred channels form the ★ Favourites zone; nearby-repeater imports create a zone of their own. Add a zone adds a standard channel list or a zone of your own; the ⋮ on a zone chooses its channels, renames it or deletes it (see Channels → Zones and standard lists).")),

        new Topic("On the intercom", "softsq", Neo.CYAN, "Soft SQ", "A smarter squelch for weak signals.",
            s("What it does", "SOFT SQ holds the radio's own squelch open and lets the app decide what you hear: the channel's CTCSS tone when it has one, otherwise a noise squelch that tells speech from static. It catches weaker stations than the radio's squelch."),
            s("The slider", "The slider next to SOFT SQ sets how strict it is, from 1 (lenient) to 9 (strict); new channels start at 5. Each step asks a little more of the signal before the audio opens, and once open it stays open until the signal is clearly gone, so speech does not chop. The number turns green while the squelch is open and amber while it is closed. On the intercom the slider sits under SCAN and ZONE and shows only while Soft SQ is on for an FM channel; with Soft SQ off, and on DMR and M17 channels, it is hidden and the activity panel uses the space."),
            s("Switching channels", "After a channel change the audio stays muted for under a second while the receiver settles, so you do not hear a burst of static."),
            s("Per channel", "Soft SQ is remembered for each analog channel. With it off, the channel's own squelch level (Channels → Edit) applies.")),

        new Topic("On the intercom", "txt", Neo.VIOLET, "Live captions", "TXT turns received speech into text.",
            s("Captions", "TXT shows live captions of received speech in the panel. The recognizer runs inside this app (Vosk); its language model downloads once on first use, is kept across app updates, and only an uninstall removes it."),
            s("Options", "Long-press TXT to choose the engine (on-device, or Google Cloud Speech with your own API key), the size of the on-device model, or keyword alerts."),
            s("In the browser", "SignalDeck Web shows the live caption and the last finished sentences on its Intercom page and has a TXT key beside SCAN, MON and REC. Its Transcripts page lists every caption the phone kept (newest first, with time, channel and caller), with a search that highlights what it finds and Download .txt; below it, Caption engine chooses on the phone (Vosk) or Google (your key, saved write-only), lists the on-device models with their size and whether they are on the phone, downloads and switches models (the phone downloads them over its own connection; progress shows on the page), deletes models not in use, and shows the phone\u2019s free space."),
            s("Keyword alerts", "Words or phrases that, when heard, vibrate the phone and post a notification; with voice announcements on they are also spoken.")),

        new Topic("On the intercom", "vfo", Neo.AMBER, "VFO", "Tune any frequency without a saved channel.",
            s("Tuning", "VFO lets you set mode, receive and transmit frequency (with repeater-offset shortcuts), power, bandwidth and tones, or colour code, slot and call target for DMR, without saving a channel."),
            s("Frequency range", "The radio tunes 136–174 MHz and 400–480 MHz only; it refuses anything else (220 MHz included) and stays where it was, so the app never sends it. If the radio does refuse a channel (for example a DMR channel without a call number), the history says so and the display goes back to the frequency the radio is really on."),
            s("While VFO is on", "The arrows step the frequency by the step you chose and the big number reads VFO. Long-press VFO to return to your channel. Save as channel keeps a frequency you want to come back to."),
            s("Band plan", "Under the frequencies, the VFO and the channel editor say what each one is used for: the US amateur band plan for 2 m and 70 cm (repeater inputs and outputs, simplex and calling frequencies, satellites, weak signal, APRS) and the other services in this radio's range (FRS and GMRS, MURS, marine, railroad, NOAA, land mobile, government). It turns amber with a caution where transmitting needs another licence, is not allowed or would disturb a special use. Amateur plans are the typical ARRL ones; your area's coordinator may differ.")),

        new Topic("On the intercom", "rec", Neo.RED, "Record and monitor", "REC saves audio; MON hears every DMR call.",
            s("Record", "REC records everything received on the channel to Download/DMR/Audio. Play them from Last heard → Recordings."),
            s("Monitor", "MON tells the radio to pass every digital call it can decode on the channel, not only those addressed to you or to the talkgroups in the channel's list. On the firmware the phone shipped with, that is the radio's own monitor mode. Receiving every call whatever its talkgroup (promiscuous receive) is not available yet: no module firmware has been proven to admit such calls on the air, so MON on a DMR channel behaves as on the firmware the phone shipped with, with every firmware. MON is for the current channel: changing channel (arrows, scan, zone, the car) switches MON off, as the radio does, and the button goes dark.")),

        new Topic("On the intercom", "pkt", Neo.GREEN, "Packet radio", "APRS, APRS-IS, TNC, parrot, Morse, DTMF, weather alerts, SSTV.",
            s("Mode pages", "APRS monitoring (on your region's APRS frequency), ISS APRS, the KISS TNC, SSTV receive (also ISS SSTV) and the parrot each open their own full-screen page when they start; for an ISS pass the page also shows the pass (see ISS). The top of the page shows the frequency, whether the radio is listening, receiving or transmitting, the signal and how long the mode has run. APRS: counters (packets since it started, stations, messages for you, last heard), switches for auto-ack, the digipeater, automatic beacons and APRS-IS, and three lists: Live (every packet as it arrives, and what you send), Stations (distance and direction; tap to open in maps) and Messages (tap one for you to reply), with Message, Beacon, Map, Settings and Stop. SSTV: the picture building up, its progress, the pictures received (tap one to view, share or delete it; long-press one to select several, tap the others, then Share or Delete; Done ends it; Combine with two or more receptions of the same picture selected makes a cleaner one: the ISS repeats its slides, so receptions from different passes can be lined up and averaged, which removes much of the noise of a weak pass. A sheet shows the result first: a partial picture is drawn at the bottom, so its true height is unknown and a thin, noisy strip can fool the automatic line-up (it says when it is not sure); choose a picture, move it with the arrows (long-press: 8 steps) or leave it out, Automatic goes back to the automatic line-up, and Save keeps it as a new picture beside them), Send picture, switching between 144.500 and the current channel, and Stop. Parrot: what it is doing, how many it has repeated, and Stop. The back arrow returns to the intercom and the mode keeps running; a green bar above the tabs brings its page back, and PKT always opens the packet tools with a Running now row at the top: one tap to the page of each mode that is running (several can run at once, for example an ISS pass waiting and M17 receive). The mode's icon at the top right of a page opens all the packet tools too. FT8 and M17 receive have pages of their own as well (see FT8 over FM and M17 receive; M17 is under Digital voice in the packet tools). Opening the app while a mode runs shows its page first."),
            s("APRS", "Every analog channel is decoded passively, below the squelch too (a damaged packet fails its checksum, so noise never shows as one): positions, messages, weather and objects go to Stations and the log. While a data mode runs (APRS monitoring, SSTV, FT8, M17) its decoders hear everything the radio receives and the speaker and SignalDeck Web stay quiet; turn MON on to listen along. Monitor parks the radio on your region's APRS frequency (Device \u2192 Region: 144.390 MHz in North America, 144.800 MHz in most of Europe, Africa and the Middle East; the button names it), can acknowledge messages addressed to your callsign (off until you turn it on: tap the Auto-ack chip on the APRS page, or APRS settings → Auto-ack) and can act as a fill-in digipeater. On a radio without a 2 m band (UHF only, such as the ANYSECU W6 phones and the Atom XL) messages are never acknowledged automatically, whatever the Auto-ack setting says; the APRS page shows \"No auto-ack (UHF)\". Send message and Position beacon transmit from your callsign, set in APRS settings: the callsign alone in its box (letters and digits, up to six) and the SSID in its own (typing CALL-7 in the callsign box is split for you). Packets are real AX.25 frames built each time from your callsign, path and text, sent as 1200-baud AFSK: a 1.6-second steady tone while the transmitter settles, then the packet twice. To the ear every packet sounds alike, so use a decoder (another radio with APRS, or APRSdroid listening through a speaker) to check what went out. Packet, DTMF and SSTV need an analog channel; on a DMR channel they are refused. For your packets to reach aprs.fi a digipeater or iGate has to hear them on your region's APRS frequency: use high power and check the raw packets page for your callsign. While APRS monitoring, a satellite pass or another mode runs, the app keeps the phone awake (and exempts itself from battery optimisation) so timed beacons and pass tracking keep going with the screen off; automatic beacons switch the GPS on so each one carries a fresh position. The packet decoder band-passes the audio and runs five slicers side by side at different tone balances, so it also copes with radios whose audio makes 2200 Hz much louder or quieter than 1200 Hz (on direwolf’s standard noise benchmark it decodes more than direwolf itself), and it repairs a packet with a single wrong bit. APRS settings → Transmit power chooses High (default) or Low on the frequencies the app tunes itself (APRS monitoring, ISS, SSTV 144.500); messages and beacons sent from your own channel use its power. APRS settings → Packet lead-in sets what is sent before each packet while the radio’s transmit audio settles: flags (the standard AX.25 TXDELAY, default), a steady tone or silence, and its length (1.6 s by default; shorter values are for testing)."),
            s("APRS-IS", "Connects to the internet APRS network. With your passcode it gates what the radio hears, beacons your position online and delivers internet messages addressed to you; without a passcode it only receives."),
            s("Two-way iGate", "Settings \u2192 Two-way iGate also sends internet messages out on the radio: when someone on the internet writes to a station this radio heard in the last 30 minutes (and the sender is not local too), the message goes out once as a third-party packet via WIDE1-1, and the station's answer comes back to the internet through the normal gating. It needs APRS-IS with your passcode and the radio on your region's APRS frequency (Monitor); PKT shows how many were sent."),
            s("Automatic beacons", "Settings \u2192 Beacon: Off, Every N minutes, or SmartBeaconing, which beacons every 30 minutes when parked, more often the faster you go (every 3 minutes above 60 mph) and once more when you turn a corner, so your track looks right on the map without filling the channel. Automatic beacons, telemetry and weather reports only go out while the radio is on your region's APRS frequency (Monitor) and no TNC client owns the radio."),
            s("Telemetry and weather", "Telemetry sends the phone's battery level, battery voltage and temperature, air pressure and the received signal as APRS telemetry; the first report and every tenth also send the names, units and scaling, so APRS sites draw graphs. Weather sends a weather report at your position with the barometer's air pressure, converted to sea level from your altitude. Both are buttons in PKT and can run every 30 minutes (Settings)."),
            s("Objects and bulletins", "Object places a marker that you own on everyone's APRS map, such as a net control point, an event or a hazard, at your position or one you type; Remove deletes it from the maps. Bulletin sends a short notice to everyone in range (BLN0 to BLN9); Bulletins lists those heard, including NWS announcements."),
            s("Text and email gateways", "Send message \u2192 Text a phone or Send an email reaches the internet through APRS: SMSGTE texts a US or Canadian phone (\"@number message\"), EMAIL-2 emails an address (\"address message\"), 67 characters in all. It needs an iGate within reach of your signal, or APRS-IS. Replies from a phone come back as APRS messages when SMSGTE knows your callsign."),
            s("Message groups", "Settings \u2192 Message groups: messages addressed to a group name you follow (for example CQ or ARES) notify you like a message to you, without an acknowledgement."),
            s("Satellite passes", "PKT \u2192 Satellite passes lists, for ISS APRS, ISS SSTV, the ISS repeater, ISS voice, SO-50, PO-101 and the other FM satellites people work (AMSAT\u2019s FM list, with frequencies and tones from SatNOGS, sorted by the next pass), the passes over you in the next 24 hours that climb above 10 degrees: when, how high, how long and where they rise and set. Orbits come from AMSAT (CelesTrak if AMSAT is down) and refresh after two days; Update orbits fetches them now. Tap a pass to track it: a minute before it rises the VFO takes the satellite's listen and talk frequencies with its access tone, corrected for Doppler (up to about 10 kHz on 70 cm) and retuned whenever the error passes 2 kHz, never while you are talking. After it sets the radio goes back to your channel. The sheet shows the satellite's direction and height and the frequencies live; Stop tracking ends it early. Higher passes are the strong ones; on SO-50 send a 74.4 Hz tone for two seconds first to switch its repeater on. Tracking an ISS APRS or ISS SSTV pass opens its page."),
            s("Is it working?", "Under each satellite's name: AMSAT\u2019s reports of the last 4 days from operators who listened to it (heard, telemetry only, not heard, and when it was last heard): green when people hear it, amber when only its telemetry is heard, grey when it seems off. Satellites switch off, fail or change schedules, so check this before a pass. Update orbits downloads the orbits and the FM satellite list again (it also refreshes by itself every few days); nothing about you is sent. SignalDeck Web\u2019s Satellites page shows the same."),
            s("VHF/UHF conditions", "PKT → VHF/UHF conditions (and SignalDeck Web’s Satellites page) answers “is it worth getting on the air beyond the usual range?”. Tropo: the next 48 hours, hour by hour, from the weather forecast’s temperature and humidity near the ground (Open-Meteo; your position is rounded to about 50 km first): grey normal, cyan slightly enhanced, green super-refraction (signals bend back toward the ground: longer range), amber ducting likely (hundreds of km). The forecast’s layers are a few hundred metres apart, so thin ducts right above the ground are underestimated; calm, clear nights after a warm day are the classic time. Aurora: NOAA’s Kp index now and forecast, and the chance of aurora overhead (NOAA’s map is downloaded whole and read on the phone). VHF aurora needs about Kp 5 at mid latitudes: point north, expect a buzzing sound. Meteor showers: the next major ones; each trail reflects 2 m for a moment, 800 to 2000 km, best before dawn. And the next satellite passes above 20°."),
            s("ISS", "The space station's packet digipeater is on 437.825 MHz (70 cm) since ARISS moved it in 2026, and its SSTV picture events use 437.550. On 70 cm a pass shifts the signal by up to 10 kHz (Doppler), more than an FM channel tolerates, so PKT \u2192 ISS APRS and ISS SSTV do not just park on the frequency: they wait for the next pass above 10\u00B0 (or the one in progress), tune a minute before the ISS rises, follow the shift every couple of seconds and come back to your channel when it sets, then wait for the next pass, until you stop. This carries on after SignalDeck restarts (an update, a reboot): it picks the ISS up again by itself. Their page shows the countdown, then the ISS's height and direction, the corrected frequency and when it sets. Fifteen minutes before a pass, orbits more than a day old are downloaded again, so a reboost of the station does not throw the pass times or the Doppler off. With Satellite passes → Record each pass on (the default), the whole pass is saved as a WAV in Download/DMR/Audio/<satellite> (about 1 MB a minute, below the squelch too), so a picture or packet that was missed can be decoded again later. Until a minute before the pass the radio stays on your channel (you can keep using it), so the top of the page says WAITING FOR THE PASS, shows the pass frequency dimmed and the time it tunes; an ISS SSTV session starts with an empty picture. ISS APRS decodes what the station digipeats; Beacon on its page (or PKT \u2192 Beacon via ISS) sends your position through it with the path ARISS, with both frequencies corrected, and only while the ISS is in view. ISS SSTV is receive only (transmitting is blocked) and saves each Robot 36 picture; during a picture the retune waits until the error reaches 5 kHz so the picture is not torn. ARISS changes the station's modes often: Satellite passes \u2192 ISS frequencies holds them (APRS, SSTV, repeater, crew voice) with a link to the ARISS status page. The ISS and satellites zone list has fixed + / plain / - channels too."),
            s("KISS TNC", "Serves APRSdroid or YAAC on 127.0.0.1:8001 on whatever channel you are on, sending and receiving. The app sends complete frames and the radio transmits them as they come (each with the same 1.6-second settling tone first); tune an analog APRS channel first."),
            s("DTMF", "Keys heard on any analog channel are logged. Send a sequence from the keypad or from your saved sequences; saved ones are kept in backups as DTMF.csv."),
            s("DTMF remote control", "PKT \u2192 DTMF \u2192 Remote lets another radio control this phone: turn it on and set a PIN of 4 to 6 digits. From the other radio, key the PIN and one command digit as one sequence (a * before and # after are fine): 1 says the position (nearest town and coordinates), 2 says the status (battery, channel, signal), 3 sends an APRS position beacon, 4 and 5 turn the parrot on and off, 6 sends the Morse ID. The phone answers on the channel 1.5 seconds after the caller lets go, with your callsign in Morse after a voice reply on amateur channels. Three wrong PINs within ten minutes lock it for ten minutes, and the PIN is never written to the history or the DTMF log. It is off by default."),
            s("Weather alerts", "NOAA SAME alerts are decoded automatically on the weather frequencies (162.400 to 162.550 MHz) and raise a notification. Where your region has no NOAA-style weather radio (Device \u2192 Region), the PKT sheet shows only a Show NOAA weather alerts button and the weather lists sit under Show all; the decoder itself still runs."),
            s("SSTV", "Receive pictures on 144.500 MHz or on the current channel, and send a picture from your gallery. Short modes: Robot 8 BW, 12 BW and 24 Color. Long modes, marked long in the picker: Robot 36, Martin M2, Scottie S2, PD 90, Scottie S1 and Martin M1 (up to about 115 s); they fit the default 2-minute transmit limit (Device \u2192 Longest transmission), and a mode longer than the limit you set is refused with the reason. After a long transmission the phone warms up (a 120 s key raised the radio's thermal zone by about 11 \u00B0C on the bench), so the next long picture waits until that zone is back within 1 \u00B0C of where it was, about 17 minutes at most; the send button tells you how long, the history says why, and a short mode can go meanwhile. A long picture also does not start while the radio zone is already at 60 \u00B0C or the battery at 45 \u00B0C, and while it runs the phone is read every five seconds: past 70 \u00B0C on the radio zone, 48 \u00B0C on the battery, or a 2 \u00B0C climb in ten seconds, the transmission is ended early and the history says so. These sit below where the phone itself slows down; the bench used stricter numbers. Two decoders, switched on the SSTV page: Any mode recognises Robot, Martin, Scottie and PD pictures from the VIS header that starts every transmission. Robot 36 continuous works like MMSSTV: it needs no header, it locks on the line sync pulses, so a picture picked up halfway is still drawn (and moved to the bottom, where its last line belongs), it keeps the line rhythm through fades instead of losing lines, it reads each line’s colour from its separator tone, and the screen shows the static until a picture comes in. ISS SSTV always uses it (ISS events are Robot 36). Pictures, and partial ones of 16 lines or more, are saved to Download/DMR/SSTV."),
            s("Decode a recording", "PKT → SSTV or APRS → Decode a recording (also at the bottom of the SSTV and APRS pages) finds the pictures or packets in a recording after the fact: a pass recording (Satellite passes → Record each pass), a REC recording, or one from anywhere with Upload a recording… (WAV, MP3, M4A/AAC, OGG/Opus or FLAC, any sample rate; it is kept in Download/DMR/Audio/Uploaded so it is listed next time). SSTV finds every mode SignalDeck receives from the header that starts each picture (Robot, Martin, Scottie, PD and more), plus Robot 36 pictures whose header was lost in a fade on a pass; a picture found both ways is saved once. Pictures go with the received ones, named after their mode and the time they were on the air (…_rec.png; _partial when a fade cut it short). APRS lists every packet with its time and writes the list next to the recording (.aprs.txt). It runs in the background, much faster than the recording plays (a ten-minute pass takes seconds), on its own decoders: the radio, the speaker and live reception are not touched, and nothing is sent, digipeated or gated. SignalDeck Web has the same on its SSTV page."),
            s("RTTY and PSK31", "PKT \u2192 RTTY and PSK31 are the keyboard chat modes of fldigi and other sound-card programs, used by clubs and emergency groups. Pick RTTY 45 (45.45 baud, 170 Hz shift, Baudot) or PSK31 and Listen: the decoder finds the signal anywhere in the audio and follows it, and prints only while a clean signal is there, not static. Type a line and Send to answer on the frequency being received (or on 2125 Hz mark for RTTY and 1000 Hz for PSK31 when nothing is). Long text is split into several transmissions of about 26 seconds each. Capital letters are slower in PSK31 than small ones. On the bench firmware (FW22 or later) RTTY goes out through the module's tone generator (clean mark and space tones from the modulator); PSK31 keeps the audio path, since its phase reversals are not tones."),
            s("Packet terminal", "PKT \u2192 Terminal connects to a packet bulletin board (BBS), node or another station's terminal on the current channel with AX.25 connected mode, the way a TNC does: enter the callsign (with its SSID, for example N0ABC-1), optionally up to two digipeaters, and Connect. Type a line and Send; what the other side sends appears below. Every transmission starts with this radio's 1.6-second settling tone, so each exchange takes a few seconds; frames that get lost are sent again, up to six tries 15 seconds apart before the link is given up. Incoming: accept lets other stations connect to you (you get a notification). It needs your callsign in APRS settings."),
            s("Simplex repeater (parrot)", "PKT \u2192 Parrot on this channel records each transmission heard on the current channel and sends it back a second after it ends, up to 26 seconds. A station can check how it sounds, or two stations that cannot hear each other can talk through you. Very short key-ups are not repeated. On amateur channels, with your callsign set in APRS settings, the playback ends with your callsign in Morse at most once per station-ID interval (ten minutes, or your region's: Device \u2192 Region). The squelch must close on silence (a squelch level above 0, or Soft SQ), or the parrot would repeat static. It stops when you change channel; each repeat is listed in the channel history."),
            s("Morse trainer", "PKT \u2192 Morse trainer teaches Morse code with the Koch method on the phone's speaker (nothing is transmitted). Each lesson adds one character in the usual LCWO order, starting with K and M. Play 5 groups sends five groups of five characters at the character speed with Farnsworth spacing; type what you copied and Check: at 90 % or better the next lesson opens. Set the character speed (5 to 35 WPM, 20 is a good start) and the spacing speed with the - and + buttons; your lesson and speeds are remembered. Sending practice: tap and hold the KEY for dits and dahs; after a short pause the app's Morse decoder shows what it read and your speed."),
            s("Voice keyer", "PKT \u2192 Voice keyer holds three recorded messages (named CQ, Net preamble and My ID at first; tap a name to rename it). Record, speak, Stop: up to 25 seconds from the phone's microphone, with silence at the ends trimmed and the level evened out. Listen plays it on the phone; Send transmits it on the current analog channel after a 1.5-second lead, with your callsign in Morse after it when ID is on and the channel is an amateur one."),
            s("ID timer", "Amateur rules ask for your callsign at intervals during a contact and at its end: every ten minutes in the US; Device \u2192 Region sets your country's interval where it is known (for example five minutes in the Netherlands), and you can change it there. Amateur channels are those inside your region's amateur bands. On them the timer starts with your first transmission after you last identified; once the interval has passed the phone vibrates and reminds you as you key (unless Morse ID after I talk does it for you). Any Morse ID restarts it; after saying your callsign, tap I just identified in the Voice keyer. PKT shows the time left."),
            s("Morse", "Morse code heard on an analog channel, such as a repeater's identification, is decoded and written to the channel history with its tone and speed; when it contains the callsign in the channel's name it is shown as the repeater's ID, confirming you hear the repeater you programmed (5 to 40 words per minute; Settings \u2192 Morse decoder turns it off). It needs a clean keyed tone: voice, static and DTMF are ignored, and a message shows once it has ended and contains a callsign (or at least eight characters of text), so stray tones are not taken for Morse. Morse decoding pauses while packet audio (APRS and other AFSK packets) is being received and for 2 seconds after it, because packet tones through the radio can look like keyed Morse; a Morse ID sent within those 2 seconds is not decoded. Send my callsign in Morse transmits your APRS callsign on the current channel. Settings \u2192 Morse ID after I talk adds it at the end of your transmission on amateur channels (2 m, 1.25 m, 70 cm) at most every ten minutes, the identification amateur rules ask for; it goes out like the roger beep, before the radio unkeys, and is skipped when the transmission ran to within 3 seconds of the transmit limit (the radio's own timer would cut it). On the bench firmware (FW22 or later) the Morse ID goes out through the module's own tone generator instead of the phone's audio path, so it needs no 1.5 s of lead and is not shaped by the audio path's filters; on stock firmware it goes through the audio path as before."),
            s("The PKT key", "PKT lights while APRS monitoring, SSTV receive, the TNC or the parrot is running.")),

        new Topic("Pages", "report", Neo.GREEN, "Logbook", "Your contacts, and the stations the radio heard.",
            s("Opening it", "PKT \u2192 Logbook. Entries are newest first; contacts are green, stations only heard are grey."),
            s("Stations heard", "With Log heard on (the default), the radio logs stations by itself: DMR callers whose ID has a callsign in the RadioID list, every APRS station decoded, and callsigns in Morse identifications. One entry per station and mode per hour; the frequency is the channel it was heard on."),
            s("Contacts", "Add contact starts an entry for now on the current channel, with 59 as the reports. Tap any entry to edit the callsign, frequency, mode, reports, name and notes, to mark it a contact (QSO) or only heard, or to delete it."),
            s("Callsign lookup and grid squares", "With Look up on, callsigns heard or logged are looked up in the free HamDB directory (US and Canadian licences and some others; only the callsign is sent, and answers are kept for 30 days): the name, location and grid square fill in by themselves, and each entry shows the distance and direction from you. Look up the callsign in an entry does it on demand. The top line shows your own grid square and how many grid squares you have worked (contacts only, four-character squares, as the VUCC award counts them). Net control check-ins get their names the same way."),
            s("ADIF", "Export ADIF writes every entry to Download/DMR/Logbook as an .adi file (ADIF 3.1) and offers to share it, for logging programs and QSL services such as LoTW or QRZ. Grid squares and locations go out as GRIDSQUARE and QTH. DMR entries are mode DIGITALVOICE, submode DMR; stations only heard carry SWL, so a logging program does not count them as contacts.")),

        new Topic("Pages", "map", Neo.GREEN, "POTA and SOTA", "Parks and summits on the air: activate, or work the activators.",
            s("Open it", "PKT → Logbook → POTA / SOTA (it says Activating … while you are), or SignalDeck Web’s Logbook page."),
            s("Activate", "In a park or on a summit: Activate a park (type its reference, e.g. US-1234, or pick one of the parks within 60 km of you; POTA is asked for an area rounded to half a degree) or Activate a summit (e.g. W0C/FR-001). SignalDeck checks the reference with POTA or SOTA and shows the name. Then Log a contact for each station: callsign, reports (59 by default), their park or summit for a park-to-park contact, notes; the frequency is the one the radio is on. A station already logged on that band in the same UTC day under your activation is flagged as a duplicate. The card counts today’s contacts against what counts as an activation (POTA 10 in a UTC day, SOTA 4)."),
            s("Upload the log", "Export ADIF writes Download/DMR/Logbook/<your call>@<reference>-<UTC date>.adi (the name POTA asks for) with MY_SIG / MY_SIG_INFO and MY_POTA_REF or MY_SOTA_REF, the other station’s POTA_REF or SOTA_REF, and STATION_CALLSIGN (your callsign from the APRS settings), then offers to send it; upload it at pota.app or sotadata.org.uk. End the activation when you leave; its contacts stay in the logbook."),
            s("Hunt", "On the air now lists the activators spotted on POTA and SOTA, the ones this radio can work first (FM on 2 m and 70 cm), then the rest (HF, CW, digital: shown dimmed). Tap one to tune the VFO to it or to log it with its park or summit. Most activations are on HF; VHF/UHF FM ones are local, so check the list now and then.")),
        new Topic("Pages", "help", Neo.VIOLET, "Exam practice", "Practise for the amateur licence exams.",
            s("The pools", "PKT \u2192 Exam practice has the three current US question pools: Technician (Element 2, 2026\u20132030, 409 questions), General (Element 3, 2023\u20132027, 423) and Amateur Extra (Element 4, 2024\u20132028, 599), with their figures. They are the official NCVEC pools (public domain), in the machine-readable edition by Russ Olsen. Everything works offline."),
            s("Practice exam", "Draws one question from each group, the way the real exam is put together: 35 questions for Technician and General (26 to pass), 50 for Extra (37 to pass). There is no feedback until the end; then you get the score, pass or not, and every miss with the right answer. Your best score is kept."),
            s("Study and review", "Study a subelement goes through all of its questions in random order and shows the right answer after each. Missed questions brings back every question you got wrong (in an exam or in study) until you answer it right.")),

        new Topic("Pages", "contacts", Neo.AMBER, "Nets near you", "Nets and get-togethers on your channels: on now, coming up, reminders.",
            s("Opening it", "Intercom menu \u2192 Nets near you, or PKT \u2192 Nets near you. The page refreshes every minute while it is open."),
            s("On the air near you", "Two sources. NetLogger, the program many net controls log their nets with, publishes the nets in session: SignalDeck shows the ones whose frequency is one of your channels (or whose DMR talkgroup is on one of your DMR channels), with net control, how many follow it and when it started. Tap one to tune the channel, or to see who has checked in (callsign, name and state only). And the radio itself: a long run of transmissions from several stations on one channel (20 minutes, a dozen transmissions) shows as \"Sounds like a net\", named when the captions catch \"this is the \u2026 net\". Weather and other receive-only channels are left out."),
            s("Coming up", "Nets that come back, soonest first: the ones you added, the ones NetLogger logged on your frequencies in the last week (weekly, or daily when held on four or more days), and the ones the radio heard on the same channel at the same time on the same weekday two weeks running (or three days in a row). Tap one to tune; long-press for more."),
            s("Adding a net", "Add a net to a channel (bottom of the page), or in the channel editor under Nets on this channel (each net is stored with its channel, so it follows the channel when it is renumbered, backed up or shared): a name, the channel, the days, the start time, how long it runs and notes such as net control or how to check in. It shows in Coming up, gets the reminder, and tapping it tunes the channel. Long-press a net you added to edit or delete it. Long-press a net found by NetLogger or by the radio and Add it as my net to keep it with your own name and days."),
            s("Near you or not", "NetLogger gives a frequency, not a place, and many towns share one. SignalDeck keeps a net in the main lists when it is near you (a state in its name or in the logger's details is yours, the repeater's callsign is net control's, or the repeater's town is in its name) or when it is on one of your own channels and nothing points elsewhere. The rest go under Same frequency, maybe elsewhere: a net only sharing a nearby repeater's frequency, or one whose name, state or net control's call district points to another area. Long-press any net to say it is near you or not; SignalDeck remembers your answer. Your state comes from your position (Android's geocoder) and stays on the phone."),
            s("Reminders", "Remind me: a notification 10 minutes before each net in Coming up. Tell me when a net starts: a notification when a NetLogger net opens on your channels (checked every 5 minutes). Both are off until you turn them on; tapping the notification opens this page. NetLogger is asked at most once a minute, as it requests."),
            s("Elsewhere on the air", "The other nets in session on 2 m, 70 cm and DMR talkgroups, for interest; a DMR talkgroup net can be heard by adding its talkgroup to a DMR channel's receive list. Tap one for its check-ins.")),
        new Topic("Pages", "messages", Neo.AMBER, "Message forms", "ICS-213 and ARRL radiograms for emergency and traffic nets.",
            s("Open it", "PKT → Message forms, or SignalDeck Web’s Messages page. New ICS-213 (the General Message: to, from, subject, date, time, message, approved by) or New radiogram (number, precedence, handling, station and place of origin, time filed, date, to, phone, text, signature; the check, the word count of the text, is filled in for you)."),
            s("Send or read", "Read on air shows the form in large type to read over a voice net. Send by APRS splits it into APRS messages to a callsign (67 characters each, one every 12 seconds; the radio must be on an analog channel and your callsign set); Send by DMR text sends it to a contact or talkgroup in 120-character texts on a DMR channel; Send by Winlink puts it in the Winlink outbox as one e-mail to callsigns or e-mail addresses (the form laid out to read, so anyone can read it, plus a code line SignalDeck uses), sent at your next Winlink connection; Save keeps it in the list. Share sends the form as text through any app."),
            s("Receive", "When another SignalDeck sends you a form, its parts (APRS messages addressed to you, or DMR texts) are collected, or it arrives whole in a Winlink message, and, once all are in, in any order, the form appears in the list with a notification and a history line. Reply starts a new form addressed back to the sender.")),
        new Topic("Pages", "search", Neo.CYAN, "Packet finder", "Find the BBSs, nodes and Winlink gateways around you.",
            s("What it does", "PKT \u2192 Packet finder (or SignalDeck Web's Packet page) listens on the usual 1200-baud packet frequencies one after another and lists every packet station it hears that is not plain APRS: Winlink gateways, BBSs, nodes (their NET/ROM broadcasts and ID beacons), station IDs and beacons, and stations heard in a connection. For each: the frequency, the best signal, how often and when it was last heard, and what it said. It only listens; it never transmits."),
            s("How long", "Nodes and BBSs identify only every 10 to 30 minutes, so a short look finds little: let it run an hour or two, or add a schedule (Scheduled operations \u2192 Packet finder, for example overnight). It stops by itself if you transmit, change the channel or a tracked satellite pass starts, and the radio goes back to its channel (or VFO) when it ends. Settings: the frequencies (in MHz; empty means the 2 m packet frequencies 144.910 to 145.090 MHz; add your area's 70 cm packet frequencies if you know them; Use my channels fills in the frequencies of your own analog channels the radio tunes, a start on a UHF-only radio such as the ANYSECU W6+, where the 2 m list does not apply), minutes on each, and hours in total."),
            s("Using a station", "Tap a station to tune its frequency and open the packet terminal with its callsign filled in, or, for a Winlink gateway, Winlink with the gateway set. Clear the list to start a fresh search. Winlink also lists gateways on its website (winlink.org, RMS Channels).")),
        new Topic("Pages", "messages", Neo.VIOLET, "Pager", "Send a POCSAG page to one RIC or several, in one transmission.",
            s("Open it", "PKT → POCSAG page, or SignalDeck Web → Pager. The frequency starts as the channel you are on. 1200 baud is the usual speed; 512 and 2400 are there too. The function code is 3: alphanumeric text, which alphanumeric pagers display. A numeric-only pager (function 0) is not sent yet."),
            s("Who it goes to", "Type RIC numbers, or the name or callsign of a contact that has pager RICs. Several fit in one transmission: separate them with spaces or commas. A contact with more than one RIC is paged on all of them. Your own RICs are set in PKT → APRS settings."),
            s("Sending", "Send keys the radio at low power on that frequency. A page is about two seconds on the air: the radio fills its buffer before it keys, then the page, then a short tail. If you are not already on a low-power wide channel there, the radio tunes a low-power VFO, waits for the retune to settle, sends the page, and comes back to the channel you were on. Signing, which is on unless you tap it off, puts your callsign and a colon at the start of the text. A SignalDeck that hears it treats that as the sender and can reply; an ordinary alphanumeric pager shows it as the start of the message. The page goes through the module's symbol engine, so it sends only when the module reports bench firmware from FW21 on. On the firmware the phone shipped with, Send says so and does not key."),
            s("Receiving", "PKT → Hear pages listens on the analog channel you are on, below the squelch, and files each page under the contact that owns its RIC. A signed page from an unknown RIC (your callsign and a colon at the start) files under that callsign. A page with neither files under the RIC number: tap it to open the thread, then Save as contact or Mute. On bench firmware the voice filter is held open. At 512 baud on this phone the audio is restored first, undoing a high-pass of about 7.5 ms that sags a long run of the same bit. The offset taken off is the average over the preamble, and during a run of the same bit the previous bit is kept until the level is a quarter of the eye past the threshold. Padding after the text is not shown. The held-path equalizer is not used at that speed. At 1200 and 2400 baud the page uses this phone's held-path equalizer and is not restored. On the firmware the phone shipped with, Hear pages says it needs the bench firmware and does not start: that receiver's audio is not something a plain slicer can read. An address word that does not check, or that needs more than one bit repaired, does not open a page, and a page is listed only when a preamble came just before it and a message word checks. A damaged address is not shown as some other number. Messages → the scan icon is monitor mode: receive only, stepping through the pager frequencies (long-press the icon to edit them) and waiting about two and a half seconds on each. It stays while a preamble is coming in, and for about a second after that so the batch can finish. A page for one of your RICs raises a notification.")),
        new Topic("Pages", "voice", Neo.VIOLET, "M17", "Hear M17 digital voice, and talk back when the module firmware can send it.",
            s("What it is", "PKT \u2192 M17 receive listens for M17, the open digital voice mode (4FSK at 4800 symbols per second, Codec 2 voice), on the channel or VFO frequency you are on, and plays what it decodes on the phone's speaker: the caller's callsign, who it is for (a callsign, a reflector module or @ALL) and their short text message are shown and go in the history and the Logbook (mode M17). Encrypted transmissions are shown but not played."),
            s("How it works on this radio", "This radio was made for FM voice: its receiver removes everything below about 250 Hz, where M17 carries much of its signal, so an ordinary M17 demodulator decodes nothing from its audio. On the firmware the phone shipped with, SignalDeck rebuilds the missing part with an equalizer that uses the symbols it has just decoded, calibrated with test transmissions for each phone model. Measured on the Ulefone Armor 26 Ultra: 300 of 300 voice frames exact on test transmissions at the standard deviation, and a spoken test message over the air came through clearly. The ANYSECU W6+ has its own calibration: its receiver cuts the low tones harder than the Armor's, and 99 of 100 voice frames came through exact on a test transmission. The Unihertz Atom XL has its own too: its radio's sound card runs about 0.01 % fast, which the calibration and the receiver follow, and 89 of 100 voice frames came through exact on a test transmission (a little less than the Armor; the learning described below can improve it). The ANYSECU W6Plus DMR has its own as well: about 80 of 100 voice frames came through exact on a test transmission (its receive audio is noisier than the W6+'s, so more frames miss; the learning can improve this too). Other phones use the Armor's calibration until theirs is measured, and may decode less well or not at all. When the module reports a bench firmware (a version other than DMR003.UV4T.V022), SignalDeck instead asks the module to hold its voice filter open and uses a fixed equalizer measured for that phone, checked before the sync search. With either equalizer, a clean call of at least 20 frames that the error correction confirms can fit a new equalizer for this phone; it is kept only when a later call, 6 dB weaker or from another station, decodes at least as well, and the note at the bottom of the M17 page says what happened. It improves a calibration but cannot make one: on a phone whose calibration decodes nothing, there is nothing to learn from. A transmission stays one listing when it runs longer than 20 seconds, and a gap of about a second in the middle does not split it. Long-press the note at the bottom of the M17 page to go back to the shipped equalizer.  Audio the module is still muting is not searched, so a closed squelch does not become a contact. The Armor 26 Ultra has that measurement. A phone without one stays on the calibrated equalizer. The hold is sent again after you release the push-to-talk, because letting the carrier drop turns the voice filter back on."),
            s("What it needs", "A fairly strong signal (the tests ran near -94 dBm). On the firmware the phone shipped with, M17 opens every transmission with a short preamble, which SignalDeck uses to lock on, so a transmission already in progress when you start listening is skipped until the next one. With the module's voice filter held open, SignalDeck can lock onto a transmission that is already in progress. While it decodes a transmission the radio's own sound (which would be a buzz) is held back and the decoded voice plays instead, on the speaker, in SignalDeck Web and in the spectrum; between transmissions you hear the channel as usual. On a phone whose radio drives the speaker by itself, SignalDeck cannot hold that sound back, so the buzz stays audible under the decoded voice; the M17 page says so. (The ANYSECU W6+ plays through SignalDeck, so this does not apply to it.)"),
            s("Switching to DMR", "M17 receive (and page receive) needs an analog channel, so selecting a DMR channel while it runs stops it, on every module firmware. On bench module firmware SignalDeck also gives the radio its normal DMR settings back first: M17 receive holds a filter setting there that would otherwise take the sync off your DMR transmissions."),
            s("Talking back", "On the firmware the phone shipped with, you cannot talk back on M17: that transmitter filters out the low tones and limits the deviation, and M17 radios cannot decode what it sends (measured). When the module reports a bench firmware with the symbol engine (a version other than DMR003.UV4T.V022), Hold to talk on the M17 page sends your voice as M17 to everyone (@ALL). Your callsign is the one in APRS settings. It ends at the transmit limit (Device \u2192 Longest transmission, 2 minutes unless you change it), and past 30 seconds the heat guard applies as for voice. A short tail follows the last word so the ending is not cut off. It needs an analog channel. Stop M17 ends listening; the back arrow keeps it running with a bar on the intercom. SignalDeck Web has an M17 panel on its Packet page (start, stop, who is talking, what was heard), and browsers that are listening hear the decoded voice too."),
            s("Text messages", "On a bench firmware, the M17 page has a message box and Send. The text goes to the channel's M17 destination, or to everyone (@ALL) when the channel has none, under your APRS callsign. It uses the same symbol transmitter as voice and takes under two seconds. Texts you send and texts you receive are listed on the M17 page and in Messages, one thread per callsign, with every text to @ALL in the shared M17 everyone thread. Each one is also a line in the intercom history. The firmware the phone shipped with can receive these texts and does not send them. If part of a text is lost, the history says the frames were lost and the text is not shown. SignalDeck Web's Packet page has the same box: who it is for, the text, and the texts sent and heard.")),
        new Topic("Pages", "ft8", Neo.CYAN, "FT8 over FM", "The WSJT-X digital mode, on an FM channel, with automatic QSOs.",
            s("What it is", "PKT → FT8 over FM runs FT8, the digital mode of WSJT-X: 15-second slots, short structured messages (calls, grid square, signal report) and contacts that run by themselves. Here it rides on the FM channel you are on, like any other audio mode, so it talks to stations sending FT8 audio on that FM channel: another SignalDeck, or WSJT-X through an FM radio. Agree on a simplex frequency with the other station; avoid the national calling frequencies. On the bench firmware (FW22 or later) the 79 tones go out through the module's tone generator instead of the audio path; the history line says so."),
            s("What it cannot do", "This radio receives FM only, so it cannot hear normal FT8, which is sent on SSB (144.174 and 432.174 MHz, and on HF). On FM the receiver lets only the strongest transmitter through, so each slot carries one station on the channel, not dozens as on SSB, and FT8's famous weak-signal reach mostly does not carry over: FM needs a usable signal before it passes anything but noise. Expect a little more range than voice, not dramatically more."),
            s("The screen", "The bar at the top is the slot clock: the time in the current 15 s slot and its period (1st: :00 and :30, 2nd: :15 and :45), red when you transmit in it. Under it, the waterfall of the channel's audio, 200 to 2800 Hz: the red lines mark your transmit frequency and width; tap the waterfall to move it (on FM it matters little). Then the QSO in progress and the station's state, and the list of decodes, newest first: time, signal in dB (in 2500 Hz, approximate), DT (the time offset in seconds), audio frequency and the message. CQs are green, messages to you amber. Your own transmissions are listed under Sent."),
            s("Making contacts", "Tap a CQ in the list to answer it: the app transmits in the other period and runs the exchange the way WSJT-X does (your grid, their report, R and your report, RR73, 73), logging the contact in the Logbook (mode FT8) as soon as the reports are exchanged. Call CQ calls until someone answers, then does the same with them. Halt TX stops transmitting; if nobody answers, it stops by itself after 8 tries (RR73 after 2). Send text sends one message of your own: any standard message, or up to 13 characters of free text (A-Z, 0-9, space and + - . / ?). Your callsign comes from APRS settings. A callsign FT8 counts as non-standard (more than three letters after the digit, or an unusual prefix) can only be sent in full in a message type that has no room for a grid or report, as in WSJT-X; the history says so once when you start, and your CQ then goes out without the grid. In the reports that follow it goes as a short code the other station learned from that first message (shown as <CALL>), so a contact still completes, and a caller with such a call is answered even though its first reply carries no grid."),
            s("Settings and clock", "FT8 settings: the grid sent with your messages (4 characters, about 100 by 200 km: empty uses the phone's location, a typed one is fixed, - sends none) and Clear list. FT8 needs both stations' clocks within about a second: the phone sets its clock from the network, and the settings show the average DT of recent decodes, which tells how far apart the clocks are. Each transmission is 14 seconds with the lead-in this radio needs. Stop FT8 ends it; the back arrow keeps it running, with a bar on the intercom to come back. SignalDeck Web has the same on its Packet page.")),
        new Topic("Pages", "mail", Neo.GREEN, "Winlink e-mail", "E-mail by radio through a Winlink gateway, or over the internet.",
            s("What it is", "Winlink is the amateur radio e-mail system used by emergency services and travellers: your callsign is your address (CALLSIGN@winlink.org), and you can write to other callsigns or to any internet e-mail address. PKT \u2192 Winlink opens your mailbox: Inbox, Outbox (waiting for the next connection) and Sent. The same mailbox, with writing, connecting, settings, the session log and attachments, is on SignalDeck Web\u2019s Messages page. You need an amateur licence and your callsign set in PKT \u2192 Settings."),
            s("Please report", "Winlink in SignalDeck is new and has not yet been tested with the real Winlink system: it was tested against a test gateway over the radio and a test server over the internet, which follow the same protocol. If you use it, please tell us whether it worked (or what went wrong, with the session log): the notice at the top of the Winlink screen opens SignalDeck's issue page on GitHub."),
            s("Detailed log", "Winlink \u2192 Settings \u2192 Detailed diagnostic log (also offered at your first connection) records, for each session, the time of every step, the protocol bytes both ways and every radio frame. Your password is never in it; the messages' data only if you tick the second box. After a session, Session log \u2192 Share log (SignalDeck Web: Download log) sends it: please do, whether it worked or not, it is how Winlink in SignalDeck gets fixed."),
            s("Trying a real gateway", "To help confirm it works, try one session with a real gateway or over the internet and report: your phone, whether it was by radio (gateway callsign, frequency, how far) or internet; whether it connected and logged in; whether your message arrived (send one to your own e-mail address) and whether mail came back; how long it took. If anything failed, open Session log and copy it into the report (the login answer is already hidden). Start with one short message to yourself."),
            s("Writing", "New message: To (callsigns or e-mail addresses, separated by commas), an optional Cc, a subject and plain text. Put in the outbox stores it; nothing is sent until you connect. Messages are compressed for the radio; keep them short, a page of text takes minutes on 1200-baud packet. Reply and Forward quote the original; Delete removes a message (from the outbox it will then not be sent)."),
            s("Connect: radio", "Tune the channel of a Winlink packet gateway (RMS; listed at winlink.org under RMS channels, usually 1200 baud on 2 m or 70 cm), then Connect: radio and enter its callsign (e.g. N0ABC-10), and digipeaters if you need them. SignalDeck calls it in AX.25 connected mode, sends the outbox, collects your mail and hangs up. Expect a few minutes: every transmission starts with a 1.6-second lead-in and frames lost on the air are sent again; the Packet terminal cannot be used at the same time."),
            s("Gateways near you", "Winlink \u2192 Gateways \u2192 Open winlink.org opens Winlink's gateway list (RMS Channels) in your browser: tap RMS List, choose Packet, then CSV File (if the buttons are cut off on the phone, turn on the browser's Desktop site). Back in SignalDeck, Import the CSV opens Android's file picker, where the file you just downloaded is at the top of Recent (or in Downloads). SignalDeck Web's Messages page imports the same file from a computer. Repeat it now and then: gateways come and go. SignalDeck keeps the 1200-baud packet gateways on frequencies this radio tunes and lists them nearest first, with distance and direction from the phone's last known position (worked out on the phone, never sent). Tap one to tune its frequency and connect, to tune and listen first, or to make it your gateway. Packet finder: listen on the nearest 10 sets the packet finder to their frequencies, to check which ones you can actually hear."),
            s("Connect: internet", "Connect: internet does the same exchange with the Winlink system (the CMS) over the phone's internet connection: handy to test your setup, or when there is no gateway in range but there is a signal."),
            s("Account and password", "The first connection with a new callsign creates its Winlink account. Set a password for it at winlink.org, then enter it under Winlink \u2192 Settings: Winlink asks for it at every login (secure login; only a one-time answer computed from it is sent). The password is kept only in SignalDeck's private settings: never shown, logged, put in a device report, a backup or Android's cloud backup. The optional grid square is sent to the gateway when you log in."),
            s("Session log and attachments", "Session log shows the last connection line by line (the login answer is hidden). Received attachments are listed under the message: tap one to open or share it. When new mail arrives you get a notification, and PKT shows how many are new.")),
        new Topic("Pages", "contacts", Neo.CYAN, "Net control", "Run a net: check-ins, traffic and a report.",
            s("Starting", "PKT \u2192 Net control. Name the net (the last name is remembered) and Start the net on the current channel. A clock shows how long it has run; the net keeps running if you close the sheet."),
            s("Check-ins", "Type a callsign and Check in, or tap one of the stations heard in the last 30 minutes (DMR callers with a RadioID callsign, APRS stations, Morse IDs; names come from the logbook). Stations checking in more than 15 minutes after the start are marked Late. Tap Traffic, Late or Out on a station to flag it; stations with traffic are highlighted. Long-press a station to remove it."),
            s("Ending", "End the net, then Share the report (name, channel, times, net control and the numbered check-ins with their flags) or Add to logbook to log every check-in as a contact. Past nets are listed under Net control; tap one for its report, long-press to delete it.")),

        new Topic("Pages", "signal", Neo.GREEN, "Band scope", "See which frequencies in a band are busy.",
            s("Open it", "PKT → Band scope (or the PKT tools button at the top of any mode page), or SignalDeck Web → Scope. Choose a band (2 m, 2 m FM simplex, 70 cm, 70 cm FM, GMRS/FRS, marine VHF, and NOAA weather where your region has weather radio; Show all bands lists it everywhere) or Custom range (from and to in MHz and the step in kHz, anywhere inside 136–174 or 400–480 MHz, up to 1200 steps; the sheet shows how long a sweep will take) and Start."),
            s("What it shows", "The radio steps across the band and reads the signal strength at each step. The cyan line is the latest sweep (the one in progress is drawn step by step over the previous one), the amber line the strongest seen at each frequency since Start or Clear peaks, and below it the waterfall: each row one sweep, newest at the top, from dark (noise) through cyan and green to amber and red (strong). Under the graph: the strongest signals at least 8 dB above the band's noise, with the channel name when one of your channels is there."),
            s("How fast", "About a second a step: after every retune the radio needs 0.7 s before its signal reading is right (measured: earlier readings are 15 to 20 dB low), then the reading itself takes 0.1 to 0.5 s. So NOAA weather (7 steps) takes about 7 seconds, 2 m FM simplex (81 steps) about a minute and a half, all of 2 m in 25 kHz steps about 3 minutes and GMRS/FRS (421 steps of 12.5 kHz) about 7 minutes; a narrow custom range with only the channels you care about comes round fastest. The line under the title shows the steps, the time a sweep takes (an estimate until the first sweep is done) and the step being measured; the frequency in the strip is the one being measured now (green), and the intercom's bar shows it too. It shows activity that lasts: repeaters, nets, beacons, interference, not a single short call. On the Unihertz Atom XL a step takes about a tenth of a second: its radio settles in about 50 ms after a retune and answers a reading in a few milliseconds (measured 2026-10-30), so the same band takes about a ninth of the time, and its scanner moves on from a quiet channel after half a second instead of one and a half."),
            s("Listen and stop", "Tap the graph (or a peak) to read a frequency, then Listen here: the scope stops and the VFO tunes there. The scope only receives; while it runs the speaker and the decoders are quiet. When it stops, the radio goes back to your channel. It stops by itself when you press Talk, for a scheduled operation and for a satellite pass, and it does not start while a pass is being tracked or begins within 15 minutes.")),
        new Topic("Pages", "scan", Neo.VIOLET, "Scheduled operations", "Start something at a set time, every week or once.",
            s("Open it", "PKT → Scheduled operations → Schedules, or SignalDeck Web → Settings → Scheduled operations. The list shows each schedule, when it runs next and a switch to turn it off; tap one to edit or delete it, Add a schedule for a new one."),
            s("What it can do", "Listen to a channel (optionally recording it the whole time, into Download/DMR/Audio/<channel>), scan the zone, APRS monitoring on your region's APRS frequency, SSTV receive (on 144.500 or a channel you choose), send one APRS position beacon, run the packet finder, or check your Winlink mail: by radio (the gateway you last connected to, on the channel you choose; the radio goes back afterwards, and a check never holds the radio more than 20 minutes) or over the internet. The result (sent and received) goes in the history. Tick weekdays for a weekly schedule, or none for once on a date; set the start time and how many minutes it lasts."),
            s("When it runs", "SignalDeck sets an exact Android alarm, so it starts on the minute with the screen off (it grants itself that permission with root). When the time is up, the radio goes back to the channel it was on and switches off what the schedule switched on. Only one runs at a time. A satellite pass being tracked always comes first: a schedule whose time overlaps the pass (from two minutes before it rises to a minute after it sets) is skipped and the history says so; while you are transmitting it waits up to two minutes. SignalDeck must own the radio at that time: after handing the radio back to the stock app, schedules do not run."),
            s("Example", "Record a weekly net: Listen to a channel, the net's repeater, Record it on, Tuesday, 19:00, 60 minutes.")),
        new Topic("Pages", "locate", Neo.GREEN, "Fox hunt", "Find a hidden transmitter, or be the fox.",
            s("Opening it", "PKT \u2192 Fox hunt, or the menu of the new intercom look \u2192 Fox hunt. Tune the fox's channel first: the hunt listens on the current channel."),
            s("The readout", "The big number is the signal strength in dBm (higher, closer to zero, is stronger), with the S-meter and the peak since you opened it or cleared. Beeper on clicks through the phone faster and higher as the signal rises, so you can hunt without looking. Pointing shows the compass bearing of the top of the phone, corrected to true north."),
            s("Marks and the estimate", "Hold the phone against your chest and turn slowly: your body blocks the signal from behind, so the strongest reading is when you face the fox. Point the top of the phone that way and tap Mark: the reading, your position and the bearing are saved. After two or more marks from different places, the app works out where the bearing lines cross, giving stronger readings more weight, and shows the distance and direction from you. The map shows your marks (cyan weak, amber medium, red strong; a hollow ring is a mark where the radio heard nothing) with their bearing lines and the estimate as a green ring; Plot in its corner switches to a compact plot around you, which also takes over by itself when no map tiles load (offline). Without bearings, the strongest mark is the hint. Open in maps shows the estimate in your map app. Marks are refused while you transmit (the reading would be your own signal). Marks stay until Clear marks (it asks first), even if you close the sheet."),
            s("Prediction", "Three layers, each switched on or off under Prediction (SignalDeck remembers the choice). Bearings (on at first): each bearing line becomes a band of likely places about 15 degrees wide either side, because a compass held near the body is good to about that; with Bearings alone the estimate is the same crossing as before. Heat map (on at first): uses only how the signal strength changes from mark to mark, no bearings needed. It needs 3 or more marks at least 100 m apart, with at least 2 of them above the radio's noise floor; until then the line under the switches says what is missing. For every place on a grid around your marks (2 by 2 km with 25 m squares, made bigger when the best place sits at its edge) it asks how well a transmitter there explains your readings, with its power unknown and the signal falling off between open-ground and cluttered rates (the rate is chosen per hunt); a mark at the noise floor only says the fox is farther away than that. The map shades the likely area, cyan to red as it gets likelier, with a bright outline around the place the fox is in with 50 % probability and a faint one at 90 %. With both on, the two are combined into one estimate, which is usually better than either alone. The estimate line names the layers it used and a confidence word from the size of the 50 % outline: good (no bigger than a circle of about 100 m radius), fair (up to about 300 m), rough (bigger: usual for the heat map alone). With both off the sheet works as it did before. Honest limits: strength-based estimates are rough: walls, cars and your body change readings by 10 dB or more. Take marks in the open, spread out around the area rather than in a line, and hold the phone the same way every time. Near the fox, use Off-frequency so the readings do not all sit at the top of the scale."),
            s("Terrain", "Terrain (off at first, because it downloads and costs battery) makes the heat map take the ground into account: for every place on the grid and every mark it looks at the ground heights in between and adds the loss a hill or ridge causes (the same model as the coverage maps), so places a strong mark could not have heard from behind a ridge drop out, and a weak mark behind a hill no longer looks farther away than it is. It works on the heat map, so it needs Heat map on. The ground heights come from the open Terrain Tiles: the first time in an area the sheet says there is no terrain for this area yet and offers Download terrain with its size (usually well under 1 MB); they are kept on the phone (shared with the coverage maps), so later hunts there work offline. The fox's antenna height changes how much a ridge hides it: tap the height button to choose on the ground (1.5 m, a handheld or a box in the grass), on a roof (10 m) or on a tower (30 m). It is worked out on 100 m blocks first and then on the 25 m squares of the likeliest blocks, and remembered between marks, so a new mark costs only its own paths. The ground model knows hills, not buildings or trees, and its heights are about 55 m apart, so a small bank or a wall does not show."),
            s("Spin for the bearing", "Spin does the turn-and-listen for you and turns it into a bearing with its own accuracy. Tap Spin, hold the phone flat against your chest with its top pointing ahead, and turn slowly on the spot through a full circle; 20 to 40 seconds is right. The ring fills sector by sector as readings arrive (cyan weak to red strong) and the white tick shows where the phone points; the big line says Slower when you turn faster than about 45 degrees a second, Keep turning when you stop, and Keep going otherwise. After a full circle with readings all round (or when you tap Fit now) SignalDeck smooths the readings around the circle and takes the bearing at the strongest direction, or, when the weakest direction is the sharper and deeper feature (your body shadowing the fox behind you), opposite it. The result says the bearing, how far off it may be (from the difference between strongest and weakest against how much the readings scatter) and which feature it came from; the fitted curve is drawn inside the ring with the bearing as a green line. Save mark stores it as a mark with that accuracy, so the Bearings layer trusts a clean spin more than a quick point-and-mark (which counts as about 15 degrees). When the difference is too small (less than 6 dB, or not clearly above the scatter), there is a gap in the circle or too few readings, it asks you to spin again instead of storing a poor bearing: step into the open, away from cars and walls. With Fox signal set to Only the fox's, only readings from the fox's own transmissions count and the ring says Waiting for the fox in between, so the spin works best on a fox that transmits long or often. It needs the phone's compass and a position, and not while you transmit."),
            s("Fox signal", "On a busy channel other stations change the readings too. Under Fox signal, Any signal (the start) counts every reading, as before; Only the fox's counts a reading only while the fox itself is on the air. On an analog channel the fox is picked by its tone: Fox: … offers the channel's own tone squelch, the CTCSS tone heard right now (SignalDeck decodes it from the audio; it takes about 1.5 to 3 seconds into a transmission, and this choice appears only while a tone is heard) or any CTCSS tone from the list. A DCS fox works only through the channel's own DCS squelch, because DCS cannot be read from this radio's audio, and only with Soft SQ off (Soft SQ holds the radio's squelch open; the sheet says so). On a DMR channel the fox is its DMR ID (Last caller fills in whoever was heard last) and, if you want, its colour code; leave either empty for any. A reading counts only from 0.3 seconds into the fox's transmission, 0.7 seconds after the radio was retuned (Off-frequency, a channel change: the signal reading lags a retune) and not in the last 0.6 seconds before the transmission ends (the squelch tail, when the carrier is already gone), so it shows up a moment late. A mark then takes the average of the transmission's last few readings. Tap Mark while the fox is silent and the button says Waiting…: the mark is taken at its next transmission, where you stand then; tap it again to cancel. Auto-marks (off at first; tap to choose 50, 100, 200 or 25 m) take a mark by themselves at each transmission (each reception with Any signal) once you have moved that far from the last mark by GPS, with the compass bearing when the phone was held steady for the last 1.5 seconds and without one otherwise; never while you transmit. The choices are remembered."),
            s("Close to the fox", "Near the transmitter every reading is at the top of the scale. Off-frequency listens 10, 20 or 30 kHz above the channel, where the fox's signal is much weaker, so the readings start to change again as you move. Closing the sheet tunes back to the channel."),
            s("On the Unihertz Atom XL", "Its radio sits behind a USB bridge chip that stops the sound when a command crosses the link while a reception plays. The hunt reads the signal anyway, because it needs the readings, so on this phone readings during a reception may cut its audio for a few seconds (SignalDeck restarts the bridge by itself). The bearing and the readout are not affected."),
            s("Be the fox", "Start the fox beacon sends 5 seconds of beeps on the current channel every minute until you stop it or change channel; on amateur channels your callsign follows in Morse. PKT lights while it runs. Hide the phone, with a full battery.")),

        new Topic("Pages", "channels", Neo.CYAN, "Channels", "Your channel list, favourites and repeaters.",
            s("The list", "Each card shows the channel number, name, receive frequency, FM or DMR, and when the channel was last heard (the time if today, yesterday with the time, or the date and time). The colour code, slot, repeater shift and tones are in the channel editor, one tap away. The active channel glows and says ON AIR."),
            s("Find and filter", "The search box matches names, frequencies (type 462.6) and channel numbers. The chips show all, favourites, analog or DMR channels. The zone button at the top opens the zone list."),
            s("Several channels at once", "Long-press a channel in the list (or tap it and choose Select several) to start selecting: each tap then ticks or unticks a channel, and All ticks every channel shown (search and the filters narrow it first). The bar at the top then stars them (or unstars them when all are already favourites), adds them to a zone you pick or to a new one you name, takes them out of the zone that is open (Out of zone; the channels stay, and a zone is never left empty), or deletes them after a confirmation: they leave every zone and the channels after them move up. The cross ends selecting. SignalDeck Web has the same on its Channels page: Select, tick the rows, then the same buttons. The phone's list and SignalDeck Web follow each other: a channel or zone changed on one shows on the other within a moment, and a selection open there ends (the channel numbers may have moved)."),
            s("Zones and standard lists", "The zone button lists your zones; tap one to use it. Add a zone starts with Your own: New zone from your channels names a zone and lets you tick its channels. Under it are ready-made lists, each added as its own zone, in your region's order (Device \u2192 Region): its own licence-free services first (a list only partly allowed says so), then the lists of use everywhere, then licence-free services your region does not list, marked \"not legal here\" (they stay because you may need them elsewhere; whether you may transmit is your responsibility); lists that exist only elsewhere (NOAA Weather where there is no weather radio, the US Business and Railroad channels) are under Show all. The lists: FRS (22 channels, no licence), GMRS (the 22 channels plus repeater channels 15R to 22R, US licence needed; pick your repeater's CTCSS tone before adding), NOAA Weather (7, receive-only), MURS (5 licence-free VHF channels), Marine VHF (10, receive-only), Ham simplex (your region's 2 m and 70 cm calling channels, its APRS and FM SSTV frequencies, and in North America the common simplex channels), DMR simplex (6 channels, colour code 1, slot 1, talkgroup 99, with a Simplex contact), Business (12 US itinerant dot and star channels, licence needed), Railroad (the 96 AAR channels, receive-only), ISS and satellites (ISS voice, APRS on 437.825, SSTV on 437.550 and the cross-band repeater, SO-50, with Doppler + and - channels and the 67 Hz access tone), UHF CB (Australia and NZ, with the repeater R channels) and PMR446 (16, Europe and UK). A channel you already have on the same frequency and tones is reused rather than added twice, and adding a list again only adds what is missing. Licence-free lists are set to low power. The ⋮ on a zone: Use, Choose its channels, Rename, Delete the zone (its channels stay), or Delete the zone and its channels (only those in no other zone). A list this radio cannot use at all (Marine VHF on a UHF-only phone) is marked Outside this radio's bands, one it can use in part says how many of its channels it can; adding a list leaves out the channels outside the radio's bands and says how many."),
            s("Favourites", "Tap a card's star to add or remove it. Starred channels form the ★ Favourites zone, so the arrows and the scanner can be limited to them."),
            s("Use, edit, delete", "Tap a card for Use (switch to it), Edit, Star or Delete. The + adds a channel."),
            s("History", "A card says when the channel was last heard. The channel editor ends with a History section, and the card's History button opens the same list: everything on that channel, newest first and grouped by day: voice (with the DMR caller), texts, tones heard, Morse repeater identifications and what they said, packet traffic, recordings, your own transmissions, and the alerts and refusals that happened on it, each with its time and signal. A DMR caller in the list is a tap target for the contact. Clear this channel's history removes the lines; captions have their own page and are kept."),
            s("Receive only", "In the channel editor (phone or SignalDeck Web), Transmit \u2192 Receive only makes a channel listen-only: Talk, the side key and every automatic transmission (beacons, replies, the voice keyer, the parrot) are refused while you are on it, and its card says RX ONLY. NOAA weather, marine VHF and railroad channels are always receive only. The setting is kept in backups (in SignalDeck's extras file, so other programs reading the backup are not affected)."),
            s("Notes", "Each channel has a Notes field in the channel editor (and in SignalDeck Web's editor): who uses it, the club or owner, linking, hours, how to check in. Notes are kept in backups and can go with the channel when you share it."),
            s("Channel names", "A channel name can be up to " + com.macdmr.radio.ChannelStore.NAME_MAX + " characters in the phone's editor and in SignalDeck Web's; the counter under the field shows how many are used and turns amber at the limit. Repeaters added from Nearby repeaters are named within the same limit. A longer name that came in from an import is shortened to the limit when the channel is next saved. Codeplug tools such as OpenGD77 CPS keep shorter names (16 characters), so a long name may be cut short in a backup opened there."),
            s("Sharing channels", "The share button (the paper plane at the top) \u2192 Share channels: name the set, tick the channels (or All, None, Analog, or the channels of a zone) and tap Share. Android's share sheet opens, so any app works: messages, Facebook, WhatsApp, Discord, email, Drive and the rest. The message lists every channel (frequency, offset, tone or DMR colour code, slot and talkgroup) so anyone can program it by hand, and ends with an import code (SDCP1:\u2026:END) that SignalDeck reads back. Copy text puts the same message on the clipboard, for a post. Optional: net schedules (the nets you added to those channels; on), channel notes (off unless you turn it on: notes can be personal), channel locations (off unless you turn it on: a channel's position could be your home), a SignalDeck file with the same content, and a CHIRP file of the analog channels for other radios (Baofeng, Yaesu, Kenwood and others; DMR channels are left out of it). Encryption keys are never shared."),
            s("Importing channels", "Share a message or file to SignalDeck (it is listed as Import channels in the share sheet), open a CHIRP CSV with it, or use the share button \u2192 Import from the clipboard or Import a file. SignalDeck finds the import code anywhere in the text, even when an app has broken the long line, and also reads CHIRP CSV files from other radios' software. A preview lists every channel with a tick; channels you already have start unticked, and ones this radio cannot use (outside 136\u2013174 and 400\u2013480 MHz, or not FM) are listed as left out. Import adds the ticked channels after yours, by default in a new zone with the set's name; nothing you have is changed. Notes and net schedules that came with them are kept (a switch in the preview leaves them out); the nets show in Nets near you."),
            s("Editing", "Every field in the channel editor has an info button that explains what it does on this radio. Analog channels need a frequency, power, bandwidth and optionally CTCSS or DCS tones; Soft SQ and its level can be set here too. An M17 channel is wide FM with M17 on top of it: a destination (@ALL, or a callsign, including one picked from a contact on the phone) and a channel access number from 0 to 15. SignalDeck Web's channel editor has the same type, destination and access number. On the intercom, Talk sends M17 voice to that destination when the module firmware has the symbol engine, and says receive-only on the firmware the phone shipped with. The module's squelch is held open so weak signals reach the decoder, and the phone plays only the decoded voice: the radio's own FM audio stays off the speaker. The channel list marks it M17, next to FM and DMR. The destination and the access number are kept in a backup. A latitude and longitude gives the intercom the place name, distance and bearing: My position uses the phone's location; Open Maps shows the spot in your maps app, where Share \u2192 SignalDeck sends a place back; Paste reads coordinates or a maps link you copied. Sharing a place to SignalDeck while no editor is open asks which channel it belongs to. DMR channels also need a colour code, a time slot, a call target (a DMR ID for a private call or a talkgroup for a group call) and the talkgroups you want to hear on that channel, up to 32 (a group call's own talkgroup is added to that list when you save, because the radio passes only listed talkgroups). Talkgroup lists under the RX group list inserts a saved, named list in one tap or saves the current one; the DMRModHooks module's lists come over from the stock app. VHF channels are always wide band on this radio; narrow band makes its receiver deaf. On DMR channels, Call number from switches between typing the call number and picking it from your contacts: group contacts for a group call, private contacts for a private call; the channel stores the number either way."),
            s("Nearby repeaters", "The dish button lists DMR repeaters from BrandMeister and RadioID and FM repeaters from hearham around you, nearest first, within 15, 30, 60 or 120 miles (25, 50, 100 or 200 km where your region uses kilometres). The two rows under the distances show only FM or only DMR repeaters, and only VHF (136 to 174 MHz) or only UHF (400 to 480 MHz); the app remembers your choice. One tap adds a repeater with its channels, talkgroup contacts and a zone, and it can be undone.")),

        new Topic("Pages", "contacts", Neo.VIOLET, "Contacts", "People and talkgroups: DMR ID, callsign, pager RICs, notes, locations and history.",
            s("What a contact is", "A person or a talkgroup. A contact can hold a DMR ID (a person's radio) or a talkgroup number, a callsign (with an optional -SSID), one or more pager RICs, notes, a home location and a label for it. It needs at least one of a DMR ID, a callsign or a RIC, so an APRS or M17 station with no DMR radio is a contact too. These fields are SignalDeck's own: the radio module's contact table only ever gets the DMR numbers."),
            s("The list", "Avatars are colour-coded: cyan for a private ID, violet for a talkgroup, amber for all-call. Under the name: the DMR ID, the callsign in green, PAGER when the contact has RICs, and when it was last heard (the time if today, yesterday with the time, or the date and time, as on the channel cards). The chips show all, private or talkgroups; the search box matches names, callsigns, DMR IDs and RICs."),
            s("Callsigns from RadioID", "A private contact with a DMR ID and no callsign gets the callsign the RadioID list (Device) knows for that ID, once. The editor says when a callsign came from there; change or clear it and it stays as you left it."),
            s("One tap from anything heard", "Every callsign, DMR ID or pager RIC the app shows is a tap target: the caller in Last heard and in a channel's history, a station or a message on the APRS page, a callsign on the M17 page, and the pager page. A known one opens the contact; an unknown one offers Add to contacts (the editor opens with the identity, and the position and time it was heard with, already filled in) or Add to an existing contact (the callsign or RIC is added to a contact you pick). SignalDeck Web does the same from its APRS map cards."),
            s("Two locations, kept apart", "Home is the location you enter (a grid square such as EM12ab, or latitude, longitude) with a label, and it never leaves the phone unless you send it yourself. Last heard is filled by the app from APRS positions and is shown separately with its time and source; an automatic fix never overwrites what you typed. Both show their distance and direction from you when the phone has a location."),
            s("History", "Each contact keeps what was heard from them (an APRS packet with its position when it carried one, a DMR voice call, a DMR text, an M17 transmission, a page) and what you sent to them (a text, a voice call keyed to their ID or talkgroup, an APRS message, a page), newest first, up to 300 entries. Tap a contact to see it; an entry with a position opens in your maps app. Repeats from the same source within 20 seconds are folded into one entry."),
            s("Actions", "The + adds a contact. The green bubble on a card opens its messages (contacts with a DMR ID). Tap a card for the contact's sheet: identity, locations, notes, history, and Message, Edit, Delete."),
            s("Your own identity", "Your callsign, SSID and pager RICs are set once, in PKT \u2192 APRS settings: APRS and M17 send under the callsign, pages you send carry it as the sender tag, and the pager page listens for your RICs. Your DMR ID is in Device \u2192 Radio settings."),
            s("Backups", "Callsigns, RICs, notes and home locations travel in SignalDeck's extras file next to the five CSVs, matched to the contact by number, type and name on restore; contacts without a DMR ID are restored from there too. Contacts.csv keeps the plain layout other programs expect. The heard history is not part of a backup.")),

        new Topic("Pages", "messages", Neo.GREEN, "Messages", "DMR texts, M17 texts and pager threads.",
            s("Threads", "The list is one conversation per contact. A DMR text uses the radio's ID or talkgroup. An M17 text uses the sender's callsign, or the contact that carries that callsign; everything addressed to @ALL shares the M17 everyone thread. A page uses the contact that owns the RIC, otherwise the callsign at the start of a signed page, otherwise the RIC. A chip in front of the name says M17 or PAGE. A number after the name is how many are unread. Tap a row to open it. A page that arrives for a different thread while one is open is named in a line at the top."),
            s("Monitor", "The scan icon in the header turns pager monitor on. Sending is put away and the radio steps through the frequencies you set (long-press the icon; hertz, separated by commas). It waits about two and a half seconds on each frequency, long enough for the receiver to settle after the retune, stays while a preamble is being heard, and for about a second after the preamble ends so the batch can finish. It is off until you turn it on, and it stays off across a restart."),
            s("Sending", "Texts travel over the current DMR channel. Tap + and pick a contact or the channel's own call target, type, or tap the lightning button for a quick reply (the list is yours to edit), and send with the green button. On an analog channel the thread says so and nothing is sent. A pager thread sends with the page transmitter on the frequency you are on. An M17 thread sends an M17 text to that callsign, or to @ALL from the everyone thread."),
            s("Delivery", "Under each of your messages: green ✓✓ delivered means the other radio acknowledged it; amber ✓ sent means it went out without an acknowledgement, which is normal for many radios (the BTECH 6X2 among them) and the text still arrives; red ✖ means the radio could not send it."),
            s("Receiving", "Incoming texts appear in their conversation and in the intercom's activity panel. A private text goes to the sender's conversation. A talkgroup text goes to the talkgroup's conversation, with the sender's name over each message, so a group chat stays one thread; the radio does not say which talkgroup a text was sent on, so (as in the stock app) it is the talkgroup of the channel you are on."),
            s("Names", "Conversations show the contact's name; for a radio that is not in your contacts, the name and callsign from the RadioID list (Device), and for a talkgroup its contact name or TG and its number. SignalDeck Web's Messages page shows the same."),
            s("Contact history", "A text you receive or send is also written into that contact's history (Contacts \u2192 tap the contact), together with the voice calls, APRS and M17 traffic of the same person.")),

        new Topic("Pages", "device", Neo.GREEN, "Device", "Radio link, settings and tools.",
            s("Radio link", "The card at the top shows who owns the radio (green: this app, cyan: the stock app, amber: a problem) with the serial port and speed. Take over and Hand back move the radio between this app and the stock app."),
            s("From a browser", "SignalDeck Web → Settings shows the module firmware and whether it is the factory image, this phone's profile and its revision, the app version, the battery and processor temperatures, whether the radio is taken at boot, and whether Wi-Fi debugging is listening. Restart the module and Check for updates each ask you to confirm before they run. Installing an update replaces the app and keeps your channels and settings. The firmware loader, the Own the radio at boot switch and Allow unlisted images stay on the phone."),
            s("Exit", "Closing SignalDeck or swiping it away does not switch the radio off: the radio keeps running in the background, receiving (that is how it works with the screen off), and the module stays powered. Device \u2192 Exit SignalDeck stops it properly: it ends any transmission and everything running (scan, APRS, FT8, M17, satellite tracking, the parrot, the band scope), stops the audio and closes the radio's serial port, then either switches the radio module's power off (Turn the radio off and exit: it no longer receives or uses battery; opening SignalDeck turns it on again in a few seconds) or gives the radio to the phone's own intercom app (Hand back to the stock app and exit). The notification has an Exit button too (pull it down to see it), which turns the radio off. Satellite tracking you had set to follow every pass, Keep access after reboot and scheduled operations stay set: they start again the next time SignalDeck runs."),
            s("Root and reboots", "The radio's serial port is locked by Android's security policy; the app needs Magisk root to unlock it. Keep access after reboot installs a small Magisk module so the rules survive reboots; with it, Own the radio at boot lets the app take the radio as the phone starts."),
            s("Radio settings", "Switches for owning the radio at boot, the side PTT key, volume-up as PTT, a custom PTT key (see Custom PTT key), Soft SQ while scanning, coverage logging (see Coverage maps), voice announcements (channel changes, caller names, keyword alerts; when you change channels quickly only the channel you stop on is spoken, and while scanning only a stop on activity and the channel you end on), the roger beep, Longest transmission (see Transmitting legally \u2192 Time limit), the new intercom look, and Animated panel when quiet (the falling lines in the intercom panel on an idle channel; they always move while receiving, and turning this off saves a little battery)."),
            s("DMR roaming", "Device → DMR roaming (also in SignalDeck Web → Settings; on a phone with DMR, and so not on an analog-only radio such as the ANYSECU W6+, which also hides Your DMR ID): while you travel on a DMR repeater channel, SignalDeck switches to the nearest repeater in the current zone that carries the same talkgroup (the one the channel transmits on, or in its RX group list). It needs the repeater channels to have a location (Nearby Repeaters adds it). It only switches when the other repeater is clearly nearer, at least 5 km and 30 % closer, so it does not flip between two at the same distance; it checks every 30 seconds, at most one switch every two minutes, and never during a call, while you transmit, scan, use the band scope or a satellite pass is tracked. Each switch goes in the history (“Roaming: switched to …”). It uses the GPS while it is on."),
            s("Custom PTT key", "Any other button can transmit too: another side key, a wired headset's button, a Bluetooth PTT button, a volume key. Tap the Custom PTT key row, tap Start, then press and hold the button for about two seconds and let go; nothing transmits while learning. The Side PTT key switch stays as it is for the phone's own PTT key, and the two work side by side.\n\nSignalDeck then checks the button automatically. It refuses one that can't work: the phone's own PTT key (it already transmits), the power, home and back keys, the touch screen, the fingerprint sensor, and a button that reports letting go at once although it was held. It warns about side effects: pressing it also brought another app to the front (checked while SignalDeck is open; a button can behave differently over other apps), a volume key still changes the volume outside SignalDeck (SignalDeck puts it back when you let go), a media button still plays or pauses music, Volume-up transmits uses the same key (it is switched off), a Bluetooth button only works while it is connected. Use it anyway keeps a button that only has warnings.\n\nThe learned button works with the screen off and SignalDeck in the background: it is read with root straight from the phone's input device, so the phone still does whatever else the button does. The switch on the row turns it on and off; Forget the learned key removes it. As always, transmitting stops by itself at the transmit limit, receive-only channels refuse it, and on a phone whose profile is untested it does not transmit."),
            s("Region", "Device \u2192 Region: the country whose defaults SignalDeck uses, such as the APRS frequency. See Region."),
            s("Your DMR ID", "What other radios see when you talk on DMR channels. Change sets it."),
            s("About and license", "The Mission Statement sheet (and its card in SignalDeck Web) also shows the version, the copyright, the license in plain words (free software under the GNU GPL v3 or later, no warranty; keep the author credit, mark modified versions, no rights to the SignalDeck name or icon), where the source code and the official signed builds are, and the open-source parts SignalDeck is built with."),
            s("Contribute", "SignalDeck is a free and open-source project (GPL-3.0). If you like it, please consider helping it grow. The Contribute button at the top of the Device page, and the Contribute tile among the tools, open the ways to help SignalDeck: donate (Ko-fi, or GitHub Sponsors once GitHub has approved the account; the money buys phones to make compatible and keeps new features coming), take part (test for bugs, suggest features, talk with other users on signaldeckradio.com or GitHub), or fork the project and make your own phone compatible, then tell us so the work can be reviewed and merged for everyone. Each opens in your browser."),
            s("Mission Statement", "The button above the tools (and in SignalDeck Web, at the top of Settings) shows why this project exists: \u201CThis project is a showcase of what an Android ham radio can do. It is built for innovation, and built on the innovation, discovery and hard work of those who came before me. I hope it inspires others to create, and to look for the next step.\u201D"),
            s("Tools", "Back up writes the five OpenGD77-style CSV files (Contacts, TG_Lists, Channels, Zones, DTMF) to Download/DMR/DMR_Backups, plus SignalDeck_Extras.csv with your channel notes, the nets on your channels and each zone\u2019s exact channels (Zones.csv names channels, so two channels with the same name were mixed up; a zone edited in another program since still follows Zones.csv; other programs ignore the file); Restore reads any such folder, including codeplugs edited in the OpenGD77 CPS fork; channels outside 136–174 and 400–480 MHz (a 220 MHz channel from another radio, for example) are skipped and listed in the result, since this radio cannot tune them. The files use the same columns as the DMRModHooks module, so backups move between the module, this app and the CPS fork; saved talkgroup lists travel in TG_Lists.csv. Re-import copies the stock app's channels (on the DMR phones, the Atom XL included, you pick an area; on the W6+ and the Xplore 1 there is one list); afterwards SignalDeck says how many of the imported analog channels open only for a receive tone (the W6Plus DMR's stock app puts CTCSS 62.5 Hz on every factory channel without showing it), so a radio sending no tone is not heard there until you set RX tone type to None. RadioID list downloads the names behind DMR IDs from radioid.net. Updates shows two paths: Release (finished builds) and Beta (test builds, often made for one phone being tested), each with its newest build and what every build since yours changed; tap a path’s Update to install it in place (nothing is installed otherwise, and your data and root access are kept). Diagnostics shows the live protocol log and radio tools (module version, power-cycle, test tone) and Check backup round trip, which exports everything, restores it into a scratch copy and lists any field that would not survive; your channels are not touched."),
            s("About this radio", "Device → About this radio (a tile among the tools) describes the radio in this phone, from its profile: the radio module, the modes and bands it covers, how SignalDeck talks to it, the stock firmware, what works on it (works, partly, no, or not tested yet), its known quirks and what that means for you, and what we measured on our own test unit. Measurements come from one unit, so your radio may differ; a value nobody has measured yet says so rather than guessing. All text can be selected and copied. The same notes for every supported phone are in the project’s repository under docs/radios and on the website."),
            s("Phone profile", "The line under the phone's name on the Device page (port · speed · audio · revision) is this phone's profile; tap it for details. Tested profiles are built into each SignalDeck release and work without the internet. SignalDeck also checks the project's signed profile list (at most every 12 hours, or Check now): it can bring a newer revision of this phone's profile, a profile for a phone this version does not know yet, or an advisory. A list is used only when its signature is valid and it is not older than the one already on the phone; a built-in profile is only ever replaced by a higher revision. Use the built-in profile ignores the list's profiles altogether. An advisory warns about a problem found with a profile and, by default, switches something off: transmit, automatic take-over, or the whole profile (the stock app keeps the radio). You get a notification, the Device page shows ⚠ advisory, and the details say what and why. It is your phone: Advisories → Use it anyway asks twice, then SignalDeck works as if that advisory did not exist (for that advisory only; Apply the advisory again undoes it). Advisories lapse at their date unless renewed, and none of this needs the internet to keep working. Transmit changes apply at once, the rest the next time SignalDeck starts."),
            s("Custom ROMs", "On a custom ROM or GSI the radio still works, but Ulefone\u2019s radio audio service (PrizeTinyService and its tinyserver) is usually gone with the system partition. On the Armor 26 Ultra SignalDeck notices that by itself and moves the radio audio straight to and from the phone\u2019s sound card instead: a small helper inside SignalDeck runs through root (Magisk), switches the sound card\u2019s routes to the radio for receive or transmit, and moves the audio, exactly as the vendor service does on the stock ROM. Nothing is installed in the system and nothing changes on a stock ROM, where the vendor service is still used. Receive and transmit sound the same either way (measured: the same noise level on receive, the same tone deviation on air). "
                + "The Radio audio check says which path is in use. If it reports that the sound card path did not start, check that SignalDeck has root access in Magisk. A device report from root also lists the phone\u2019s sound card streams and mixer controls, which is what support for another phone\u2019s custom ROM is built from."),
            s("Radio firmware", "The next line shows the radio module's firmware. SignalDeck remembers the first version this phone's module ever reported as its stock firmware and keeps it for good, so you can always tell what the phone came with. When the module reports another version, the line turns amber and shows both. On a phone SignalDeck has a profile for whose module firmware can be read (not an analog-only module such as the ANYSECU W6+'s, which carries no firmware file and cannot be read), once it owns the radio it also checks that stock firmware against the signed firmware catalogue (fetched at most once a day): the module version, and the stock app's firmware file by its fingerprint. When the catalogue does not list it, SignalDeck asks once whether to submit it to the firmware project, and an amber line under the firmware line, Firmware not in the catalogue yet, stays until the catalogue lists it; tap it to submit later. Submitting opens the project's GitHub issue form in the browser with the phone model, the module version, the stock app's version and the file's fingerprint filled in; you check them and press Submit there, with a GitHub account. Nothing is sent unless you do, and nothing in it identifies you. When the stock app's firmware file is new to the catalogue as well, SignalDeck copies it (after checking its fingerprint) to Download/DMR/FoundFirmware with a SOURCES.txt, and the issue's attachment box says where it is. Attaching it is your choice: an attachment on the issue is public, anyone can download it, and the file belongs to the phone maker. SignalDeck never uploads it. Tap the firmware line to open Module firmware. That page shows the installed image, the image you chose, and whether the factory backup is verified. A load starts only after every pre-flight check is green: the module answered, the radio is idle, the stock app is paused, the battery is charging above 40 percent or above 60 percent, the file's hash matches a known image, and the factory backup is present. The bar then walks Prepare, Update, Hello, Erasing, Transfer, Finish, Restart and Verify. Erasing fills over about twelve seconds while the module clears its flash. Transfer fills as each block is accepted. Under the bar: blocks, bytes, rate, time so far, time left and retries. While a load runs the intercom, SignalDeck Web and Android Auto say the radio is busy loading firmware, and Talk does nothing until it finishes. Handshake log opens the transfer record. If the version that comes back is not the one that was loaded, the page restores the factory image by itself and says so. A stock-app version that differs from the one this phone shipped with is only a warning when the firmware file itself matches. Recovery, when the module does not answer at all, offers only that factory image. An image stays in the module until you load another one, including after a reboot. Nothing on the page changes the radio's bands or its power. If the stock app is gone and there is no verified copy, Download factory image checks the signed firmware catalogue and saves the factory image only when its signature and its hash both match. A released image that is not on the phone yet is downloaded the same way: choosing it downloads it (Download retries, and Load downloads it first if it is still missing); Check for new firmware fetches the catalogue again. It is kept only when its size, its hash and the version string inside it match the signed catalogue entry, and a copy is saved in Download/DMR/Firmware. Allow unlisted images, under Advanced, is off until you confirm it twice. It lets a file from Download/DMR/Firmware load when you type the first eight characters of its hash, the factory backup is on the phone, and the phone is a known one. The catalogue and this project do not cover that file. The switch turns off after the load. A version string that does not match restores the factory image. Restore factory still loads that image afterwards, when the backup is verified, even if the module is reporting the unlisted version. Loading module firmware is at your own risk: the released images are tested on the bench and the page checks the phone, the module and the file before anything is written, and the factory image can always be loaded again, but SignalDeck and its contributors give no warranty and are not responsible for a module that stops working or for what it transmits. Loading module firmware is offered only on phones whose flash process has been tested end to end (certified); today that is the Ulefone Armor 26 Ultra. On every other phone the Module firmware page does not open, whatever the image, and an image of your own cannot be loaded there either."),
            s("Help support this phone","On a phone SignalDeck does not know yet, or one whose profile is untested, Device → Help support this phone (also under Device report) lists the steps in order, each with its own instructions and a tick when done: 1 Run all checks (below), 2 Listen check, 3 Send the results. A step unlocks when the one before it is done. The listen check needs SignalDeck to own the radio: tap Take over, choose a channel on the Intercom page where you can hear stations right now, then Start. It has two parts, each with its own question, so the answer tells where a problem is: first 10 seconds with the squelch held open (MON), when the speaker should play something — static, or the station if one is talking (did you hear anything? if not, the sound path to the speaker is the problem; skipped on DMR channels, which have no static), and SignalDeck records 5 seconds of it, then 50 seconds with the normal squelch, which opens by itself when the station talks (did you hear the station clearly?), recording up to 20 seconds while something is heard. A station right at the squelch level sounds choppy because the squelch keeps opening and closing; that is the signal, not the app. The report shows each recording's length, level, clipping and dropouts. When you share, the station recording is left out unless you choose to include it, because it may contain other people's voices; the static recording is always included. For each part it records the signal strength each second, how long something was heard and how much audio arrived; if the signal stayed at or below the squelch level it says so. Your answer goes into the report with the measurements. Every step only listens. After each step send the results; the next version of the app (Device → Updates) carries what was learned."),
            s("Run all checks","On a phone SignalDeck does not know, or one whose profile has not been tested, the app offers this the first time it opens (Device → Run all checks, or Device report → Run all checks, any time later). One button does it all in about two minutes: closes the stock walkie-talkie app, makes the device report (including clues from the stock app's code, such as the lines it names (a field called dmr_pwd holding a GPIO path is the power line), and the radio module's device-tree entry), gives you 10 seconds to press the side PTT key, opens the stock app for 15 seconds (it first asks which app that is: the one it found, ranked by evidence such as holding the radio's serial port or shipping a serial library, Choose another app… for any app with an icon, or None to skip) to record how it starts and listens (its log, the serial ports it opens and their settings, every byte it sends to the radio module and gets back from its very first call (it is closed first so its start is seen; the bytes go into stock_serial.txt with radio IDs blanked), the radio driver's messages; do not press PTT then, the stock app would transmit) and closes it again (on a phone whose radio is a USB device behind a bridge chip, such as the Unihertz Atom XL, the radio takes the phone's USB port while it is on, so a computer on the USB cable loses the phone for those 15 seconds; the checks then switch the radio off the stock app's own way and give the port back, and the computer sees the phone again a few seconds later; a plain force-stop would leave the radio on and the port taken until a restart), runs the radio probe (it asks the module who it is on the serial ports: the DMR version query and, for analog modules of the SA818 family, their AT handshake and version query; only the ports the walkie-talkie app itself uses when they are known, never anything that tunes or transmits; again with the module switched on if it did not answer, on phones with a profile; on a phone whose radio is behind a USB bridge chip, such as the Unihertz Atom XL, it stops the stock app's radio service for about 10 seconds, switches the radio on itself, asks the bridge chip and the module for their versions only, then switches the radio off, gives the USB port back and starts the service again; a computer on the USB cable loses the phone meanwhile; when the module answers there, the phone's serial ports are not swept), and, if you choose Checks + trial, takes the radio for about 30 seconds receive only (nothing is transmitted) to record whether the module answers (its version, how the serial port was opened and whether the module announced itself at power-up), the signal strength and 5 seconds of the received audio (on an untested phone it listens on 446.00625 MHz with the radio's squelch open, so the audio path carries noise even when nobody is talking), then gives the radio back to the stock app; on a phone whose profile lists the commands its stock app sends (the Armor 20WT), the trial also lists every other command SignalDeck sent and whether the module answered it. On an untested phone the trial also checks, still receive only, whether the module opens its squelch with squelch 0 alone or only with the monitor command (and so whether an empty audio capture means anything), the received noise level at this profile's module volume and at the Armor 26 Ultra's (saved as rx_level_v<volume>.wav), how soon after a retune the signal reading is steady (five retunes, a reading every 150 ms), and which frequencies around 136, 174, 400 and 480 MHz the module accepts (a receive channel written at each edge and 5 kHz outside it); the trial then takes about a minute and a half. On the Ulefone Armor 3WT the trial instead records whether the phone's radio service (extmodule) is running and listening, the bridge chip's build date, 5 seconds of its receive audio stream with the frame size (which tells its audio rate), which frequencies from 100 to 480 MHz the module accepts (receive channel writes at 100, 120, 130, 136, 174, 400, 470 and 480 MHz and just outside some of them), and the module's raw answers to two queries its intercom app never sends (the signal reading and version queries of the Armor's command set); nothing is keyed. When the stock app had not run since its data was cleared, its databases are read again after its 15 seconds, once it has made them; and when the probe could not set the radio port's speed, the summary says so, since only the trial opens that port the stock app's way. SignalDeck's own log is added with packet, position, message and caller lines removed and callsigns and IDs masked. The report ends with a summary and a draft profile: every setting SignalDeck needs to drive this phone's radio (the stock app, the module's protocol, the control port and its speed, the audio path, the power line, the PTT key and the broadcasts the stock app listens for, the SELinux rule), each with how sure the report is and what it saw, or unknown; nothing in it is applied, it is what the maintainers write the phone's profile from. Both are also at the end of 00_SUMMARY.txt, and report.json holds the same facts as data, so two reports can be compared on a computer (scripts/report_diff.py in the SignalDeck repository). At the end, Send shares the zip by e-mail, a messenger or a cloud drive, GitHub issue opens a pre-filled issue to drag it into, and the folder stays in Download/DMR/DeviceReport (adb pull /sdcard/Download/DMR/DeviceReport from a computer)."),
            s("Radio audio check", "Device \u2192 Device report \u2192 Radio audio check, for \u201Cno sound from the radio\u201D on DMR or analog. Choose the channel and tap Start (if the radio is still starting up, the check waits up to 30 seconds for it). On an analog channel (easiest: a NOAA weather channel, which always has a station) it first holds the squelch open for 10 seconds (MON), so receiver noise must arrive even with nobody on the air: that alone shows whether the audio path works (it waits for the radio to confirm MON first, and says so if the radio never answers). If the squelch then stays open with no signal, it tries the stock app\u2019s way of closing it and reports what worked. Then it listens for a minute with the normal squelch; on DMR have someone talk on the talkgroup meanwhile. "
                + "SignalDeck records what the radio reports (each reception, and on DMR who called which talkgroup, with caller IDs shortened), whether audio arrived from the phone\u2019s radio audio path (the vendor audio service on the Armor, the radio\u2019s audio serial port on the Xplore 1) and how loud it was, how the phone plays it (volume, speaker or Bluetooth), and, on phones whose audio goes through the vendor audio service, checks the system for that service, which custom ROMs may lack (on the Armor 26 Ultra SignalDeck then reads the radio audio straight from the phone’s sound card, see Custom ROMs; on other phones a Magisk module that adds Ulefone’s audio service and its PrizeTinyService library from the phone’s stock firmware brings the audio back: SignalDeck asks Android for that library when it is there). "
                + "It ends with the most likely cause (for example: this ROM lacks the audio service; no audio even with the squelch open; the talkgroup is not in the channel\u2019s RX list, so the radio drops the calls) and puts the details in the device report to share. If the radio refuses to switch MON on (it can, right after many quick channel changes), SignalDeck retries three times and the check says so instead of blaming the audio path. Nothing transmits and the audio is never kept."),
            s("Device report", "For a phone without a profile, the Device report tile collects what a profile needs, captures what the side PTT key sends, runs the root-only radio probe, and shares the result or opens a pre-filled GitHub issue. The report and the PTT capture only read; Transmit test session is the one item in the menu that transmits (see Transmit test session). The probe sends the radio module's version query on the serial ports, including USB serial ports (ttyACM, ttyUSB: there it also sends the Agold phones' version queries), and, until the next reboot, allows this app to open them. It leaves alone any port another app or service has open (the stock app, a vendor radio service, or this app while it owns the radio: Hand back first) and ports that belong to the modem, GPS or Bluetooth. It tries other line speeds on a port only when it can set that port's own speed again, puts every port's line settings back afterwards, and says so plainly if one is not back (a reboot restores it). It switches the module's power on only if you choose Probe + power pulse. With root the report also lists, for phones it does not know yet: the phone's name from its vendor partition (a GSI reports a generic name), the USB devices and what each interface is (a radio behind a USB chip shows as serial plus sound), the radio-related system properties, vendor radio services and programs (names and sizes), programs listening on local network ports, programs holding USB serial or sound devices with their command lines, installed Magisk modules (names, versions and file names, never their contents), and, in the PTT capture, which key a raw key code becomes in the phone's key layout files. SignalDeck's own harmless SELinux denials are counted instead of listed. Before log lines go into the report, personal details are taken out: long numbers such as DMR IDs and phone numbers, e-mail addresses and callsigns, and, in the radio frames the stock app logs, the radio ID, the call number, the encryption key, caller details and text messages (shown as ##). On phones whose stock app logs its radio frames (Unihertz Atom XL, Ulefone Armor 3WT), the summary also says when the module answered the stock app, so a probe that could not reach the module's port does not look like a dead module. Radio firmware files (root, in the Device report menu) lists the radio chip images the phone carries, in its radio folders and inside the stock walkie-talkie app (found through root while SignalDeck has it switched off): name, size, a SHA-256 fingerprint and the module version written inside. A file whose fingerprint SignalDeck already has (its own factory and bench images, and the signed firmware catalogue's rows) is marked already known with what it is, for example a phone's factory image or a stock copy kept for research, so nobody needs a copy of it. A file in /sdcard/intercom/dmr comes with a warning: on some phones (Unihertz Atom XL, Ulefone Armor 3WT) the stock walkie-talkie app loads a .bin from that folder into the radio module by itself when its name sorts after the module's version, so nothing should be left there by accident; SignalDeck never writes there, and copies go to Download/DMR/FoundFirmware. The apps' own files in /sdcard/DMR (serial captures, recordings, reports, logs, backups) are left out; there only a .bin of at least 100 kB with a module version inside is listed, such as an image you copied there yourself. The list goes into the report; files are copied only if you tick them, into Download/DMR/FoundFirmware on the phone with a SOURCES.txt, and nothing is sent anywhere. They belong to the phone maker: share them only privately, and only if the SignalDeck maintainer asks."),
            s("When the radio module stops answering", "SignalDeck checks that the radio module takes commands. At start-up it asks for the module's version; with no answer within 3 seconds it restarts the module for real (power off, a pause, power on), twice at most. While running, if a channel change, MON or squelch command has waited 6 seconds for an answer while the module still sends signal readings, SignalDeck asks once more and then restarts the module and puts the channel, MON and the receive audio back (a few seconds without reception, at most once every two minutes, never while transmitting). Each restart is noted in the history. A module that still does not answer usually needs the phone restarted; please send a device report then."),
            s("Second radio test", "Device → Device report → Second radio test (also step 2 of Help support this phone): for a new or untested phone, with any other FM radio. Choose an unused analog channel on a frequency the other radio can use too (VHF or UHF; licence-free examples: PMR446 446.00625 MHz in Europe, FRS 462.5625 MHz in the USA), set the other radio to the same frequency with no tone, then follow the steps: key it and talk for 5 seconds; keep it quiet while SignalDeck holds the squelch open (MON); key it without a tone and then with 100.0 Hz while SignalDeck listens with a 100.0 Hz tone (a temporary copy of the channel). SignalDeck measures each step itself: how soon the radio reports a reception (this sets the scan time per channel), how loud the received audio is, whether the squelch closes, whether MON was refused and whether the tone squelch works, and suggests profile values. This phone only listens. The results go into the device report."),
            s("Transmit test session", "Device → Device report → Transmit test session, for someone testing transmit on a phone they are adding (usually in their own fork of SignalDeck; the steps are section 3.3 of the certification guide, docs/DEVICE_CERTIFICATION.md in the SignalDeck repository). It transmits, so it opens only when this phone's profile may transmit: a verified profile, a profile that allows this session before it is verified (the Ulefone Armor 20WT; only the session's own keys go out, the Talk key and everything else stay off), or, in a fork's own build, a profile the fork set to verified = true (the report then says the flag came from that build), never while an advisory has switched transmit off, and never while Restricted mode keeps transmitting off. First a safety sheet: switch on each rule (a licence for the frequency, a dummy load or low power on a simplex frequency you may use, short keys, stay with the phone, watch the heat), then Start. It asks what measures your signal (for example an RTL-SDR) and which radio receives it, then runs the steps, each with Skip and Stop: an FM key of 5 seconds; three 2 second keys that must each end when released; one key SignalDeck does not release, which its transmit limit must end (for its whole run the session uses its own 28 second limit, whatever Longest transmission says) (the only long key; Release now ends it early and the step counts as skipped); an optional 10 second key while you measure the carrier offset and deviation, which you type in; a 5 second group call on a DMR channel (DMR phones), with whether the other radio showed your caller ID; on a phone whose stock app sends DMR texts in another format than the Armor's (the Blackview Xplore 1), one short DMR text to the channel's call number, with the radio's delivered or failed report and whether the other radio showed it exactly; and five 3 second keys for the heat. SignalDeck keys through its normal transmit path, so a receive-only channel refuses as usual. Steps that need an FM or DMR channel ask you to choose one on the Intercom page first. A Release now button is on screen during every key. For each key it records the time (UTC), the channel and frequency, power, mode, how the radio was keyed, the module's status replies (SEND_START, SEND_STOP) with their times, who released it, and the battery and processor temperatures before and after; you answer whether the receiving radio heard it and can add notes. At the end you can pick a recording of your transmissions (SignalDeck stores its name and SHA-256, not the file) or give a link to it. The result is tx-report.json in the device report folder (Download/DMR/DeviceReport), with a readable section in report.txt and 00_SUMMARY.txt; the callsign and DMR ID set in the app are replaced by <callsign> and <dmr id>. Share the report zip, or tx-report.json on its own, with your transmit test results issue or pull request."),
            s("Build identity", "Every device report (report.txt, report.json and 00_SUMMARY.txt) and every transmit test says which build made it: the version, the git commit, branch and repository it was built from (with any password or token removed from the address), whether it had uncommitted changes, when it was built, the SHA-256 of the key it is signed with, and whether that is the project's release key (official build) or another (fork build). It also gives the profile's id, revision and verified flag, whether transmit was switched on by overriding an advisory, and whether verified = true comes from the official profile list or only from this build. The maintainer uses it to rebuild exactly what was tested."),
            s("Report summary", "Every shared report starts with 00_SUMMARY.txt: the phone, the build (see Build identity), the profile and its revision, the radio module, the audio path, the latest Radio audio check and second radio test, a transmit test session when there is one, every radio command with how often it was sent, answered, refused or answered slowly, and how many signal readings were the module’s “no reading” value. The report folder in Download/DMR/DeviceReport gets it as soon as the report is made, so a folder sent by hand has it too (Share writes it again with the latest checks); a copy of the shared zip also stays there."),
            s("Radios that do less", "SignalDeck shows only what this phone's radio can do. On a radio without DMR (the ANYSECU W6+), the Contacts and Messages tabs, DMR channel types, Your DMR ID, DMR roaming, the RadioID list, the firmware loader and the DMR text choices in message forms and the emergency sheet are hidden, and the VFO is FM only. On a radio that tunes only part of the bands (the W6+: 400–470 MHz), whatever parks on a frequency it cannot reach is hidden or refused: APRS monitoring on 2 m (your region's APRS frequency), SSTV on 144.500, the NOAA weather alerts and the satellites that send outside its bands; the VFO starts on your channel and its arrows jump over what it cannot tune; the packet finder leaves out frequencies it cannot reach (on the W6+ all its 2 m defaults: add UHF ones in its Settings); every message about frequencies names this radio's bands. On a radio that reports no signal strength (the W6+), the band scope is hidden, the signal meter on the intercom and on the mode pages says RECEIVING or QUIET instead of S-units, and the fox hunt can only be the fox. POCSAG pages need the symbol engine of the HR-C7000 bench firmware, so a radio with another module does not offer them. On the ANYSECU W6+ and the W6Plus DMR your voice goes from the microphone straight to the radio, and the sounds SignalDeck makes itself (APRS, Morse ID, tones, RTTY, SSTV, FT8) go through a relay that feeds the phone's own audio to the radio while it transmits; SignalDeck sets the media volume for that moment and puts yours back, so a muted phone still sends them. SignalDeck Web follows the same rules."),
            s("Unihertz Atom XL", "Tested 2026-10-28 with radio module DMR006.U4A.V067: SignalDeck receives and transmits on it like on the Armor 26 Ultra (FM, DMR voice and texts, APRS, DTMF, SSTV, recording, scanning, the signal meter), and takes the radio by itself when it opens and, with Own the radio at boot, after a restart (about a minute after the phone starts). What is different from the Armor: Its module is UHF only (400–480 MHz), so what parks on 2 m is not offered (APRS monitoring on 2 m, SSTV on 144.500, the NOAA weather alerts, satellites outside the band). The radio is a USB device behind a small bridge chip on the phone's only USB port, so while SignalDeck has the radio a computer on the USB cable does not see the phone (use Wi-Fi for SignalDeck Web and adb). While SignalDeck has the radio it keeps the phone awake (the processor, not the screen), so receptions with the screen off are not missed; that costs some battery, and Exit or Hand back lets the phone sleep again. Take over stops the stock app's radio service and switches the radio on itself; Exit and Hand back switch it off and give the USB port back. Hand back takes about 20 seconds: it first checks that the bridge chip answers before it switches the stock app back on (the stock app would otherwise try to update the bridge's firmware; if the chip stays silent, restart the phone before opening the stock app). The receive audio comes from the radio's own USB sound card, opened at each reception like the stock app does and kept open for a moment after it, so the end of a transmission (where an APRS packet sits) still reaches the decoders. The bridge chip stops the sound when another command crosses the same USB link while it streams, so during a reception the signal meter (and SignalDeck Web's) holds the reading from just before it and moves again when the reception ends. Fox hunt, the coverage log and the checks still read the signal during a reception because they need it, and may cost a short drop. If the bridge still stops the sound now and then, SignalDeck restarts the bridge, which costs a few seconds of audio, and carries on, so a long SSTV picture can lose a few lines. Sometimes the bridge's reception signal sticks after the radio is switched on; SignalDeck notices receptions from the signal strength instead (a moment later than usual). When two receptions in a row go unreported it restarts the bridge once; if the signal stays stuck, the history asks you to restart the phone, which clears it, and the Device report shows the state. MON on an analog channel opens the sound at once, without waiting for that signal. The caller of a DMR call is read when the call starts and again after it ends, because the bridge cuts the radio's messages short while sound flows. While SignalDeck has the radio it switches on Android's \"Disable USB audio routing\" (developer options), so Android does not treat the radio as a USB headset, and puts the setting back when it lets go (after a restart too). Hand back warns when /sdcard/intercom/dmr holds firmware files: the stock app loads those into the radio module by itself when it starts. Module firmware shows the module's version but opens no loader: this module is updated through the bridge chip, not the way SignalDeck loads the Armor's. POCSAG pages need the Armor's bench firmware and are not offered. Channels: with none, SignalDeck offers to import the stock app's channels from the area the stock app is on (it has ten areas: Default and regional FRS/PMR lists; channels without a name are named after their area and number); Device → Re-import imports another area. Only channels come over: the stock app keeps no talkgroup lists or contacts SignalDeck uses. Agold's App block (Settings) stops apps a few minutes after the screen goes off and blocks their start at boot, which would cut the radio off: SignalDeck opens App block for itself once when it takes over; switch off Boot blocker, Start blocker and Background cleanup there. Receiving does not heat it: with the radio on and the screen awake the phone settled about 3 °C above idle (processor near 36 °C, battery near 31 °C), the same during a 15-minute reception as after it (2026-10-29)."),
            s("ANYSECU W6Plus DMR", "The W6Plus with DMR (the phone calls itself V69) has the W6+'s body but a DMR radio module of the Atom XL's family (DMR006.U4A), connected straight to the phone. Checked 2026-10-29 for receiving: SignalDeck takes the radio, reads the module, imports the stock app's 128 channels and your DMR ID, plays FM reception through the phone's speaker (the volume keys set it), and the signal meter works; Soft SQ uses its normal levels. Its module is UHF only (400–480 MHz), so what parks on 2 m is not offered. Module firmware shows the module's version but opens no loader: the module keeps the maker's firmware, and POCSAG pages, which need the Armor's bench firmware, are not offered. Transmitting was checked the same day in a test cage at low power: an FM key and a DMR group call (colour code, talkgroup and DMR ID decoded from a recording), and the 28-second limit unkeys it; the phone's transmitter sat about 1.6 kHz high against the test receiver, within DMR's tolerance, though a hotspot may need its offset adjusted. Since then the profile counts as verified: SignalDeck may own the radio at boot and transmits on it. Received DMR voice is still quieter than FM, and DMR texts are not checked yet. Your voice goes from the phone's microphone straight to the radio; sounds SignalDeck makes itself (APRS packets, Morse ID, tones, SSTV pictures, FT8) go through the relay the stock app uses for its network gateway, which puts the phone's own audio on the radio's microphone input while it transmits (the speaker stays silent). APRS, RTTY, FT8 and SSTV sent this way were all decoded by a second phone in a test cage. That route is a voice path (nothing below about 300 Hz, treble lifted, a cut above 3 kHz), so M17 cannot be sent on this phone."),
            s("Untested profiles", "Some phones have a profile written from their stock app and owners' reports that has never run on that phone (the Device page shows \"untested\" next to the port). On those, SignalDeck does not take over the radio by itself, neither when it opens nor at boot: tap Take over yourself, after making a device report and running the radio probe. If taking over fails, the stock app is switched back on straight away. Transmitting is switched off on these phones until the profile has been tested (the talk key, the side PTT key, packet modes and the web all refuse), so the radio only ever listens. The exceptions are the Ulefone Armor 20WT and the Blackview Xplore 1: there the guided Transmit test session (Device report → Transmit test session) may key the radio, so an owner can collect what testing the profile needs; every other way to transmit stays off until it is verified. On the Blackview Xplore 1 the app sets the radio's PTT line to receive before it switches the module on, the way the stock app does, and drives the radio the way that app does: it keys the transmitter with the PTT line, never with a command; the microphone starts only when the radio reports that it is transmitting (if that report does not come within 2 seconds, no audio is sent) and runs a fifth of a second past the release; no new key within 1.5 seconds of the last release (an earlier press waits for the rest); a shorter start-up exchange (no microphone or interrupt setting), and after each channel the interrupt and polite settings the stock app sends; DMR texts in the stock app's format (a shorter header, UTF-8), with received texts read in either encoding, and in the Transmit test session a DMR text step that checks it; no module firmware loading (its stock app's updater carries no image). The Ulefone Armor 20WT has an untested profile too: its radio is on another serial port than the Armor 26 Ultra's and opened with its own stock app's serial library. SignalDeck drives it the way its stock app does: a shorter start-up exchange with the module (no microphone or interrupt setting), the analog channel volume its stock app uses, the audio opened 0.6 seconds before the transmitter is keyed (a release before then sends nothing), no new key within 2 seconds of the last release (an earlier press waits for the rest), Import from the stock app reading its own channel files (areas Default, USA_FRS and the others), and no module firmware loading (its stock app has no update path). The Ulefone Armor 3WT has an untested profile too, and it never transmits (not even in the Transmit test session) until it is tested. Its radio sits behind a USB bridge chip like the Atom XL's, with an older DMR module, and the phone's own radio service (extmodule, which on a custom ROM comes from the owner's Magisk module and must be running) owns it; SignalDeck talks to that service the way the phone's intercom app does, over two local connections, one for commands and one for audio, and stops the intercom app while it has the radio. Its module's digital channels have no time slot setting, so on this phone the channel editor shows \"Time slot: chosen by this phone's radio module\" instead of the slot and mode choices, and the channel list and Intercom page show the colour code alone; simplex DMR with other radios is the safe use, repeater channels may not work. The module has no known signal-strength command, so the S-meter, band scope and fox hunt readings stay off; DMR receptions show no caller ID yet. Channels can be set from 100 to 174 and 400 to 470 MHz, what the intercom app accepts; below 136 MHz is not confirmed for the module. The side key reaches only the kernel on the custom ROM seen so far, so SignalDeck listens for it with root as the phone's default custom PTT key (Device \u2192 Custom PTT key shows it; it keys nothing while transmit is off). No module firmware loading. The Unihertz Atom XL is tested: see Unihertz Atom XL. The ANYSECU W6+ is tested for receive (2026-10-28), so SignalDeck takes its radio over by itself like a supported phone; its transmit was confirmed on the air the same day, so it transmits like a supported phone too. It has a different radio altogether: an analog UHF module (400–470 MHz, no DMR) that SignalDeck drives with its own text commands. On it SignalDeck offers the stock app's 128 channels when it first takes over, tunes, sets the tone (including the stock 62.5 Hz) and squelch, and hears the radio through the phone's camcorder input, so recording, captions and the decoders work; SignalDeck plays the radio itself, as on the other phones (the module's own speaker path stays off and the module's volume stays fixed), so the volume keys set the loudness and Soft SQ, the volume and muting act on what you hear; the sound comes a fraction of a second after the signal. Soft SQ uses its own thresholds on this phone (its receive audio is quieter above 3 kHz than the Armor's): level 1 lets barely readable signals through, level 9 only clean ones, static never opens it. The W6+'s audio cannot carry sub-audible tones, so on a channel with a receive tone Soft SQ keeps the module's squelch at 1 and the module checks the tone; without a tone the module's squelch is held open and Soft SQ alone decides. While Soft SQ is on, the channel's Squelch level is not used. Data modes (SSTV, FT8, M17) on the W6+ keep the radio's own squelch at the channel's level (at least 1): with its squelch fully open this radio decodes APRS worse. Its module gives no signal readings, so the S-meter stays dark. On a radio without DMR the Contacts and Messages tabs (DMR contacts and texts) are hidden, every channel is analog (the channel type, the Relay setting and the Analog/DMR filters are not shown; Nearby repeaters lists only FM repeaters the radio can tune, a DMR + FM repeater is added as its FM channel, and imported DMR channels are left out), and Module firmware shows the module's version but opens no loader. SignalDeck Web hides the same: its Messages and Contacts pages, the Analog/DMR filters, the channel type and the DMR log mode.")),

        new Topic("Pages", "globe", Neo.CYAN, "Region", "Your country's APRS frequency and other defaults.",
            s("What it sets", "Device \u2192 Region (the first row of Radio settings) is the country whose defaults SignalDeck uses: the terrestrial APRS frequency (APRS monitoring, automatic beacons, SmartBeaconing, telemetry, weather reports, the two-way iGate and the scheduler use it, and the ham simplex list's APRS channel), the FM calling and SSTV frequencies, the licence-free services, whether NOAA-style weather radio exists, the amateur band edges, kilometres or miles, and the station-ID interval. The sheet lists each value; values still being checked against the regulator's pages say \"to be confirmed\"."),
            s("How it was chosen", "On the first start the app takes the country of your SIM card, else the mobile network's, else the phone's language setting, once, and shows it in a card at the bottom of the intercom (\"Region: Belgium (from your SIM)\"; Change, or close the card). When the SIM and the network disagree (roaming), the SIM wins and the card names the network's country. It never changes by itself afterwards: when you travel, change it yourself. If the phone says nothing usable, nothing is chosen and the North American values stay in use (APRS on 144.390) until you choose."),
            s("Choosing", "Choose your region shows the countries with checked values; type to find any other country (it uses its IARU region's defaults: Region 1 for Europe, Africa and the Middle East, 2 for the Americas, 3 for Asia and the Pacific). Custom starts from one of the three IARU regions' values. If you changed values yourself, the app asks whether to keep them."),
            s("What changes with it", "Add a zone lists your region's licence-free services first and marks the others \"not legal here\"; the ham simplex list uses its calling, APRS and SSTV frequencies. NOAA weather lists, the band scope's weather band and the SAME alerts card are offered where weather radio exists (elsewhere under Show all). The Morse ID and the ID reminder use its amateur band edges (for example 144 to 146 MHz in most of Europe, so 146.520 is not treated as an amateur channel there) and its station-ID interval. Distances (APRS stations, the fox hunt, the map, nearby repeaters, contacts, the logbook) are in kilometres or miles as the region uses, and Distances on the sheet changes it."),
            s("Your own values", "Change next to a value sets your own (for example a local APRS frequency); Reset goes back to the region's. A frequency this radio cannot tune is saved with a warning, and what parks on it (APRS monitoring) is then not offered, as on a radio that does not tune 2 m. ISS and satellite APRS, the KISS TNC and frequencies you tune yourself are not affected."),
            s("Safe by design", "Changing the region never transmits, never starts monitoring and never changes a channel you made. It only sets defaults: you remain responsible for your licence and for following your country's rules. SignalDeck Web shows the region on its Settings page and uses its APRS frequency for its buttons; the region is changed only on the phone."),
            s("How accurate it is", "The country values come from public band plans and national rules, and some are not yet confirmed: they may be wrong or out of date for your country. Check them against your own licence and band plan. If you find a wrong value, please report it on GitHub (Issues, title \"Region data: <country>\") with the correct value and a source, such as your national society's band plan or the regulator's page, so the next release can fix it for everyone. A licence-free service in the list means the band is licence-free there for radios approved for it, not that this phone is one: such services usually need approved equipment, a power limit and a fixed antenna.")),

        new Topic("Pages", "device", Neo.CYAN, "SignalDeck Web", "Use the radio from a browser on your Wi-Fi.",
            s("Turning it on", "Device → SignalDeck Web → Web access. The card then shows the address to open (for example http://192.168.1.20:8080) and an 8-character PIN. Open the address in any browser on the same Wi-Fi network, type the PIN once, and that browser stays logged in for 30 days of use. It is off until you turn it on, and it stays on after a reboot until you turn it off."),
            s("What it shows", "Its own pages, not a copy of the phone's screen. Intercom: the channel, frequency, S-meter, receive and transmit state with the caller, the channel's history as it happens, live captions with the last finished sentences and a TXT switch, the channel arrows, SCAN, MON, REC, Soft SQ with its level, the zone, and LISTEN, which plays the radio in the browser: exactly what the phone's speaker plays (after the squelch), about a quarter of a second behind, with its own volume. Several browsers can listen at once; it uses about 16 kB/s of Wi-Fi while someone is talking and almost nothing while the channel is quiet. A small bar next to RX/TX shows the audio level. Under it: Last heard (callers and stations grouped like the phone's sheet; click one to tune its channel) and the week's alerts and events. VFO (on the Intercom and Channels pages): tune any frequency with every channel setting, the arrow step, and Back to the channel. Channels: the list of the selected zone (the Zone menu at the top switches it, for the radio too, as on the phone) with All / \u2605 Favourites / Analog / DMR filters and search; the star on a row adds or removes it from the \u2605 Favourites zone; click a channel to tune it, Edit to change it (every field of the phone's editor, with the same checks and the same i explanations), New channel to add one, Delete to remove one. Under the list, Zones: make, rename and delete zones and tick their channels (All / None work on the filtered list); a change to the zone in use applies at once. APRS: the packets and stations heard, monitoring on and off, a beacon and messages. SSTV: the picture as it arrives, the saved pictures, and Send a picture (PNG or JPEG from the computer, as Robot 24 Color, Robot 12 BW or Robot 8 BW on the current analog channel; needs Allow transmit from the web). Satellites: the pass being tracked, ISS APRS, ISS SSTV and Stop, and every satellite's passes over you in the next 24 hours (click one to track it; it replaces the current tracking after asking). Logbook: log a contact (frequency and mode filled from the channel), edit or delete entries, show contacts only, export ADIF. Under the logbook, Net control: start a net on the current channel, check stations in (names are looked up when left empty; stations heard in the last 30 minutes are one click away), mark Traffic, Late or Out, remove, end the net, and open or download any net's report. Recordings: the REC recordings, newest first, to play in the browser, download or delete. Packet: APRS-IS, the KISS TNC, the parrot repeater and the fox transmitter as switches (parrot and fox need Allow transmit from the web), Send Morse ID, the voice keyer (upload a recording from the computer into any of the three messages, play it, Send it with an optional Morse ID; the station-ID timer shows when you are due to identify), text modes (listen for RTTY or PSK31, see what is decoded, send text), FT8 over FM (start and stop it, the slot clock, the waterfall (click it to set your transmit frequency) and the decodes; click a CQ to answer it, Call CQ, Halt TX, send a message, the period and the grid; your own callsign shows as (you); answering, CQ and sending need Allow transmit from the web), the packet terminal (connect to a BBS or node, send commands, accept incoming connections), DTMF sending (your saved sequences one click away) and the DTMF heard, the weather alerts received, and all APRS settings (station, beacons, transmit power and lead-in, decoders, APRS-IS and KISS). Your callsign and APRS-IS passcode are never shown in a browser: leave those boxes empty to keep them. Exam: the licence exam practice (practice exam, study a subelement, review missed) with the figures; keys A–D answer and Enter goes on, and missed questions and best scores are the same as in the phone's Exam practice. Under it, the Morse trainer (Koch method, the same lessons and speeds as on the phone): play ten groups of five in the browser, type what you hear, Check; 90 % moves you to the next lesson. Settings: who owns the radio, Take over and Hand back, the radio module (firmware, profile, temperatures, and, after you confirm, restart the module or install an update), the browsers connected and listening, and the Device page's settings (DMR ID, side PTT, volume-up, Soft SQ while scanning, roger beep, voice announcements, keyword alerts, logbook, coverage and car settings). Own the radio at boot is shown there and changed only on the phone. Pager sends a page and lists the pages heard. Messages shows DMR, M17 and pager threads, each with a chip for which one it is, and sends on that thread. The Packet page's weather-alert panel says whether SAME decoding is on. Backup and restore there too: Back up now writes the five CSV files to Download/DMR/DMR_Backups, Download gets any backup as a .zip, Restore puts one back, and you can restore from CSV files on the computer (a backup or an OpenGD77 CPS export). The Diagnostics log there shows the phone's recent radio log, for troubleshooting from the computer. Web access itself, its PIN and Allow transmit from the web change only on the phone. Messages: your DMR text conversations, with quick replies and sending. Contacts: add, edit, delete and text contacts. Map: the APRS stations heard (at the positions they sent), every channel that has a location (whatever zone is selected; set one in the channel editor under Location) and, with Repeaters ticked, the repeaters near the phone (or, with Repeaters here, around the middle of the map wherever you moved it), on a dark OpenStreetMap; drag, zoom with the wheel or the buttons, click a marker for details or to tune a channel (close the card with its \u00D7, Esc or a click on the map). Coverage: pick Signal heard or Transmit reached, then All repeaters or one repeater (or a repeater or channel card \u2192 Coverage): the measured squares, and for one repeater its terrain prediction underneath (tick Terrain prediction; it runs on the phone and appears in a few seconds, or longer when terrain has to be downloaded). The line under the toolbar says what is shown and how the prediction is calibrated; click a square for its reading. Fit zooms to the coverage while it is on. The Repeaters layer adds the repeaters within your search radius (the same catalog as Nearby repeaters on the phone); click one for its frequencies, tones or colour code and talkgroups, then Add to my channels shows what will be programmed and adds it. The Coverage choice draws the coverage maps measured by Coverage logging: signal heard (each square in the median signal, on the phone's colour scale) or transmit reached (green: a transmission from there keyed the repeater, red: no reply); click a square for its numbers. Help: this guide, searchable. A bar under the title shows any mode that is running. The phone and every open browser stay in step: a change made on either shows on the others at once."),
            s("Decode in the browser", "The SSTV page's Decode a recording panel lists the phone's recordings (pass recordings, REC and uploads), newest first: choose SSTV pictures (every mode) or APRS packets and Decode, or Upload… a recording from the computer (WAV, MP3, M4A, OGG, FLAC, up to 200 MB), which the phone keeps and decodes at once. Progress, the stage and the packets found show in the panel; new pictures join the gallery. Stop ends it."),
            s("SSTV pictures", "On the SSTV page, click a received picture to open it in a card on the same page: the arrows (or the ← → keys, or a swipe) step through the pictures, × or Esc closes it. Share hands the picture to the device's share menu (messages, e-mail, Facebook…); browsers only allow that on the secure address (https, port 8443). Download saves it. Delete removes it from the phone after you confirm. Select (above the pictures) lets you tick several: All, Share (all of them at once) and Delete (after a confirmation); Done ends it. The gallery shows the pictures SignalDeck saved."),
            s("Phone panel", "The Intercom page also shows the phone itself, updated every few seconds. Battery: the level, charging or on battery (and the charger type), the current in mA (plus while it charges, minus while it drains), how fast the level moves in percent per hour over the last half hour and when it will be full or empty at that pace (it needs about five minutes after SignalDeck Web starts or the charger is plugged in or out), the temperature and the voltage. Cell: the signal in dBm and bars, the carrier and the network (2G to 5G), or no SIM / airplane mode. Wi-Fi: the signal in dBm and bars, the network name, the band and the link speed. NOT UPDATING appears when the phone stops answering."),
            s("Transmitting", "A browser never transmits unless Allow transmit from the web is on. With it on, the PTT button keys the radio while you hold it (or hold the space bar); letting go, switching tabs or leaving the window always unkeys. On the plain address (http://…:8080) the phone's own microphone transmits. To talk with the computer's microphone open the secure address the Device card shows (https://…:8443): the browser warns once that the certificate is the phone's own (compare the fingerprint on the Device card) and asks once for the microphone; after that PTT sends your voice from the computer. SignalDeck ends it at the transmit limit (Device \u2192 Longest transmission), and the phone stops by itself if the browser goes quiet for 1.5 s or the connection drops. Only one person can talk at a time. Every transmission started from a browser is written to the channel's history with the browser's address. APRS beacons, messages and the other transmit tools follow the same switch."),
            s("Safety", "The server only answers addresses on your own network (home Wi-Fi, hotspot) and refuses the internet. Five wrong PINs from one address wait a minute. A browser stays logged in across app restarts and phone reboots (the phone keeps only a fingerprint of each login, never the login itself). New PIN makes a new one and logs every browser out; turning Web access off closes the server. Your callsign's passcode and keys are never sent to a browser."),
            s("If it does not open", "Phone and computer must be on the same network (a guest Wi-Fi often keeps devices apart). If the card says Not running, another app is using port 8080; restart SignalDeck. The address changes when the phone joins a different network; the card always shows the current one.")),

        new Topic("Pages", "map", Neo.CYAN, "Map", "APRS stations, repeaters and channels around you.",
            s("Open it", "Intercom menu → Map, or the map icon at the top of Channels."),
            s("What is on it", "Green dots: APRS stations the radio decoded (any analog channel, APRS monitoring, ISS APRS), at their last position; APRS-IS stations are not shown. Cyan diamonds: FM repeaters; violet diamonds: DMR repeaters, within the Nearby repeaters range (15 to 120 miles). Amber pins: your channels that have a location (channel editor → Location). Blue dot: you, moving with the phone while the map is open; the soft circle around it is how accurate the fix is."),
            s("Moving around", "Drag to move, pinch or double-tap to zoom. The buttons on the right zoom in and out, go back to your position, fit everything on screen, and (the last one) show the repeaters around the middle of the map: move the map anywhere, tap it, and the repeaters within your Nearby repeaters range of that spot replace those around you. The pills at the top hide or show each kind: APRS (the stations received), Repeaters and Channels; the number is how many there are. The map remembers which ones you turned off."),
            s("Markers", "Tap one for a card: a station shows when it was heard, its path, speed, altitude and comment; a repeater shows its frequencies and tone and opens its details to add it as a channel; a channel can be used straight away. Every card can open the place in your maps app."),
            s("Coverage", "The violet Coverage pill adds your measured coverage: where each repeater was heard and where your transmissions keyed it. See Coverage maps."),
            s("Map tiles", "From OpenStreetMap (© OpenStreetMap contributors), darkened to match the app and kept on the phone for 30 days, so places you have looked at still show offline.")),

        new Topic("Pages", "signal", Neo.VIOLET, "Coverage maps", "Where your repeaters really work, measured as you go.",
            s("What it does", "With coverage logging on, the app measures each repeater wherever you hear it and checks whether it answers when you transmit. Over time the Map shows two pictures: where the repeater reaches you, and where you reach the repeater. You just use the radio normally; walks and drives fill the map in."),
            s("Turn it on", "Device \u2192 Coverage logging, or Map \u2192 the violet Coverage pill \u2192 Log coverage (the same setting). It uses GPS while it is on, and keeps working with the screen off once you have switched it on with the app open. While it is on, the radio notification says Mapping coverage. Switch it off the same way. Everything stays on the phone. On a radio without signal readings (the ANYSECU W6+) only key-ups are recorded; the Heard layer stays empty."),
            s("Which channels", "Channels that have a location: the repeater's position, which channels added from Nearby repeaters get automatically (or set it in the channel editor \u2192 Location). Key-ups are judged only on repeater channels, where the transmit and receive frequencies differ."),
            s("Heard: repeater to phone", "Each time you hear the repeater, the signal strength is stored with your GPS position (only fixes better than 50 m, at most one reading every 5 seconds unless you moved 25 m). On DMR the radio reports a call only with the channel's colour code; on analog with a CTCSS tone the app checks the tone, so other stations on the frequency are not counted. The map shows 150 m squares coloured by the typical reading, from blue (barely heard, about S3) through green to red (S9+30)."),
            s("Key-ups: phone to repeater", "After each transmission of more than half a second on a repeater channel, the app reads the signal five times in the next two seconds. A repeater keeps transmitting for a moment after you let go (its tail or hang time); if that signal stands 8 dB above the channel's quiet noise floor, you keyed it from there (green). If nothing comes back it is a no reply (red). The Last heard history notes each result."),
            s("Driving with a steady signal", "While a station keeps transmitting, a reading is stored every 2 seconds as long as you keep moving (every 5 seconds when you stand still), so a drive draws a continuous track: at 60 mph about one reading every 55 m."),
            s("NOAA weather: the best way to start", "NOAA Weather Radio channels (162.400 to 162.550 MHz) transmit all the time, so on them every reading is stored, heard or not: weak spots and dead zones show up in blue instead of staying empty. Give the NOAA channel its transmitter's location (channel editor → Location), select it, turn on logging and drive around: the map shows that transmitter's real coverage, and the prediction calibrates itself from it."),
            s("On the Unihertz Atom XL", "Coverage logging reads the signal during receptions, because that is what it maps. On this phone, whose radio sits behind a USB bridge chip, readings during a reception may cut its audio for a few seconds (SignalDeck restarts the bridge by itself); the stored readings are not affected."),
            s("While scanning", "Logging carries on during a scan: whenever the scan stops on a channel that has a location and hears it, the readings are stored for that repeater. Each channel keeps its own quiet noise floor across scan visits, so a transmission after the scan stops on a repeater is judged too."),
            s("Key-up test", "Coverage sheet \u2192 Key-up test here: on an FM repeater channel it transmits your callsign in Morse (about 3 seconds at 20 words per minute, your station identification) and records whether the repeater answered, without having to call anyone. It needs your callsign (PKT \u2192 APRS settings) and logging on, and asks before transmitting. On DMR, call the Parrot (private call 9990 on BrandMeister) instead: hearing your own call back proves both directions. Use it sparingly; repeaters are shared."),
            s("Reading the two layers", "The Heard layer usually reaches further than Key-ups: the repeater has a big antenna and more power than a handheld. Plan by Key-ups. No-reply squares are shown only for repeaters that have answered you somewhere, since a repeater with no tail never answers. Someone else talking right after you can look like a key-up; it is rare."),
            s("Live while you watch", "With the map open, new readings appear within a couple of seconds and your blue dot follows you. The prediction re-calibrates itself from the new readings at most every 2 minutes (a full recalculation takes about half a minute)."),
            s("Focus and details", "The Coverage sheet picks the layer (Off, Heard, Key-ups) and one repeater or all of them (each square then shows the best one). Tap a square for its reading, or a channel pin \u2192 Coverage to focus on it. The legend in the corner opens the sheet."),
            s("Terrain prediction", "Pick one repeater (Coverage sheet, or a repeater or channel on the map \u2192 Coverage) and the map adds faint squares: the range predicted from the hills and valleys between you and the repeater, by default (Auto) as far as the transmitter's power and antenna height can carry over flat ground, up to 50 miles, or a range you pick. It works before you have measured anything, so you can check a repeater before adding it. A picked range is a minimum: the prediction always reaches out to your position and to everything you have measured (up to 50 miles), so a reception far outside the expected range is never left off the map. The repeater's antenna height is Auto by default: once your Heard readings cover a range of distances, the app tries heights from 10 to 350 m and keeps the one that explains them best (a tall tower carries much further over the hills); with fewer readings it uses 30 m. Pick a height, or Set the exact one, if you know it. Transmitter power works the same way: Unknown assumes 50 W and lets your measurements correct the level; NOAA Weather Radio stations publish theirs (most are 1000 W), and repeater owners often list theirs."),
            s("How it is calculated", "For each square: the loss over smooth ground (the direct signal plus its reflection off the ground within the radio horizon, the earth's curve beyond it, per ITU-R P.526), plus whatever the hills between add as obstacles. Heights are taken above the surrounding ground, so a transmitter on a hill or a phone on a rise gets credit, and a valley costs signal. The transmitter's power and antenna height set the level; your measurements correct it."),
            s("How the prediction learns", "It starts from typical numbers (a 50 W repeater, a 4 W handheld, 12 dB for trees, buildings and your body). Your Heard readings shift its signal level to match what you really received; your key-ups move the limit of where you can reach the repeater. Until you have key-ups, the reach follows the Heard correction too, since it is the same path both ways. Each square's card says whether it is measured or predicted and how well calibrated the prediction is. Your altitude counts through the terrain: the ground height at your position and at the repeater is in every calculation, so a hilltop or a valley is accounted for (the phone's own GPS altitude is not used: it is typically 10 to 30 m off). Trees and buildings are not in the terrain data, so forests and towns usually come out weaker than predicted until you have measured there."),
            s("In the browser", "SignalDeck Web\u2019s Map shows the same layers: the measured squares for all repeaters or one, and the terrain prediction for one repeater (the same settings as here: antenna height, power and range from the Coverage sheet)."),
            s("Terrain data", "Heights come from the open Terrain Tiles (AWS Open Data, about 55 m detail). The first prediction for an area downloads them (a few megabytes); after that they are kept on the phone and predictions work offline."),
            s("Export and clear", "Export writes Download/DMR/Coverage/<date>/ with coverage_rx.csv and coverage_tx.csv (every reading, for a spreadsheet) and coverage.kml, which opens in Google Earth with coloured squares and green/red key-up points per repeater. Clear deletes the readings of the selected repeater, or all of them."),
            s("Good habits", "Carry the phone the same way when you compare places: a pocket or a car costs 10 to 20 dB. Do not key a repeater just to test it; use your normal conversations, and identify with your callsign as always.")),

        new Topic("Pages", "radio", Neo.GREEN, "Android Auto", "The radio on your car's screen.",
            s("In the car", "Connect the phone to Android Auto and the radio appears among the media apps (SignalDeck): on the car's app list (it may be on a later page) and as the media card on the car's home screen; tap the card for the full media screen. Press play there (or on the card) to hear the radio through the car's speakers: the radio then becomes the car's media source, like any music app, and pause hands the speakers back. Its card and media screen show a small version of the intercom panel: the zone (when the channel is in it), the channel digits (red while you transmit), frequency, mode chips, a state badge (receiving, transmitting, scanning, ready, paused) and a live signal meter. During a DMR call the chips become the talker's callsign and the talkgroup (or Private call), and the subtitle reads who is talking with their DMR ID and the talkgroup (for example N0CALL Demo Operator · 9999999 · TG 91); Radio controls shows the same on its Talking line; the channel list shows each channel's number tile. The radio keeps its connection to the radio module on the phone; Android Auto only shows and controls it."),
            s("Choosing a channel", "On the media screen, the arrow at the top left opens the channel list: Last heard first (who and what was received, newest first; tap one to tune that channel), then a tab for each zone (including Favourites once you have starred channels), with More holding the rest and All channels. Tap a channel to tune it. In Radio controls the Channels button lists the same. Previous and next, also on the steering wheel, step through the zone. The search button finds a channel by name, number or frequency, and \"Hey Google, play NOAA WX6 on SignalDeck\" works too."),
            s("Talk", "The microphone button on the media screen transmits: tap to start, tap again to stop; it ends by itself at the transmit limit (Device \u2192 Longest transmission, 2 minutes unless you change it). Receive-only channels refuse it. With Device \u2192 Car microphone in Android Auto on (the default) and the car connected over Bluetooth too, the car's own microphone is used through its hands-free link (the link takes a second to come up before the radio keys); otherwise the phone's microphone. The phone's side PTT key works as always."),
            s("Radio controls (big Talk button)", "Android Auto gives media apps only small buttons, so the radio also has its own car screen. It is off by default: turn on Device \u2192 Full-screen Radio controls in the car, then reconnect the car, and open Radio controls from the car's app list. It shows the live panel, the channel and its status, two wide buttons, TALK (green; red with STOP TALKING while you transmit) and Channels, and arrows at the top right for the previous and next channel. Channels lists Favourites first (your starred channels; until you star some it says how), then every zone and All channels; tap a channel to tune it. Inside a zone, Scan at the top scans exactly that zone (Stop scan ends it). While it is on, Android Auto lists it instead of the media app; the radio's media card, steering-wheel buttons and lock-screen controls still work. If the car does not list it, see If the radio is missing. The radio history records what Android Auto did (connected, opened the media app or Radio controls, took the sound away), so a drive can be checked afterwards. Talk works as on the media screen, with the car microphone when available."),
            s("Scan, pause", "The scan button starts and stops a scan of the zone. Pause mutes the radio's sound; it keeps receiving, decoding and logging underneath, and play brings the sound back. Pressing play in the car makes the radio the car's media source (other media pauses)."),
            s("How it sounds", "When you are not playing the radio as the car's media, anything it receives still comes through the car speakers like a navigation prompt, with the car's music turned down meanwhile; the navigation volume sets its loudness."),
            s("Messages read aloud", "Incoming DMR texts, APRS messages (over the air and APRS-IS) and NOAA weather alerts arrive as conversations: on the phone, and in the car Android Auto announces them and reads them aloud. Reply by voice and the answer goes back the way the message came: a DMR text to that ID or talkgroup (needs a DMR channel tuned), an APRS message over APRS-IS when it came from there, otherwise over the air on the current channel. Weather alerts have no reply. Diagnostics \u2192 Post a test car message shows what it looks like (its reply is never sent)."),
            s("Coverage while you drive", "With Device \u2192 Log coverage in the car on (the default), coverage logging starts when Android Auto connects and stops when it disconnects (unless you had switched it on yourself), so drives fill in the coverage maps by themselves."),
            s("Next as a talk key", "Device \u2192 Steering-wheel Next talks (tap to choose Off, Hold or Double-press; Double-press by default, only while Android Auto is connected). Hold: hold the wheel's Next button for half a second and the radio transmits until you let go; some cars send the release late or not at all, so if it keeps transmitting, press Next once more to stop. A short press still goes to the next channel. Double-press: press Next twice quickly to transmit and once to stop; a single press goes to the next channel after half a second. Double-press uses only presses, so it works even where releases are unreliable. Both need the car to pass the button itself to the app: some cars send Next only as a command, and the history then says so. Steering-wheel microphone chooses the microphone for transmissions started from the wheel. Car (as a call, the default): the car's microphone works through its hands-free link, and while that link is open the car treats the wheel as call controls, so a wheel start becomes a short \"call\" (SignalDeck: talking) and the wheel's hang-up button or End on the car screen stops the transmission; it never appears in the call log. If the car does not open its microphone within 4 seconds, that transmission uses the phone's microphone and the history says so. Phone: the phone's microphone, and the wheel's Next or play/pause stops as usual. Stop when I stop talking (Off, 1.5, 2.5 or 4 s; 1.5 s by default): for wheel-started transmissions, the radio unkeys once you have been quiet that long (or after 6 seconds if you never speak), measured against the road noise. With a mode on, the history also shows the first wheel presses of each drive."),
            s("Steering-wheel Talk", "Device \u2192 Steering-wheel play/pause talks (off by default): in Android Auto the wheel's play/pause button starts transmitting and a second press stops (the transmit limit as always). The play/pause button on the car screen still pauses the radio's sound. Only the wheel's media buttons reach an app (play/pause, previous, next): the voice button belongs to Google's assistant (it needs the Google app enabled on the phone; \"Voice commands are not available right now\" means it is not) and the phone button to the car's dialer."),
            s("Last heard", "In Radio controls \u2192 Channels, Last heard lists who and what was received, newest first, with the time and channel (and talkgroup for DMR). Tap one to tune that channel."),
            s("If Android Auto drops while you talk", "With the phone on a USB cable, the radio's own transmission can get into the cable and reset the phone's USB port: Android Auto disconnects about a second after you start talking and reconnects when you stop, and the phone stops charging meanwhile. It does not matter which Talk button you use. It depends on the frequency, not on where the antenna is (the cable itself picks up the signal): in one car a 2 m repeater transmitting on 144.770 MHz at high power dropped it every time while 146.370 MHz did not. The app notices it: the radio history notes the channel and frequency and the phone shows a notification. What helps: a snap-on ferrite choke on the cable close to the phone, a shorter, better-shielded cable, Low power for that channel (Channels → edit the channel), or wireless Android Auto if the car has it."),
            s("If the radio is missing", "Android Auto only trusts apps installed from the Play Store. For this app it plays the sound and the steering-wheel buttons work, but SignalDeck (and Radio controls) is missing from the car's app list, and tapping its card on the car's home screen opens the app on the phone instead of the car's media screen. The app checks this setting (with root): while it is off, the Device page shows Android Auto is hiding this app (tap it for the steps and a button that opens Android Auto's settings), and when the car connects the phone gets a notification and the radio history notes it. To fix it, allow Unknown sources once: on the phone open Android Auto's settings, tap the version number at the bottom ten times to unlock the developer settings, then in the ⋮ menu choose Developer settings and turn on Unknown sources. Disconnect and reconnect the car. Android Auto's desktop test head unit does not check this, so the radio appears there either way. Once, with Unknown sources already on, Android Auto connected without loading the radio at all (same symptoms); unplugging the cable and plugging it in again fixed it. The app notices this too: if Android Auto has not loaded the radio 30 seconds after connecting, the radio history and a notification say to reconnect.")),

        new Topic("Pages", "channels", Neo.CYAN, "Widget and notification", "Control the radio without opening the app.",
            s("Notification", "While the radio is on, its notification shows the channel, frequency and what is happening (ready, receiving, transmitting, scanning) with three buttons: previous channel, scan or stop scan, next channel. Tap the notification to open the app."),
            s("Home-screen widget", "Device → Home widget asks the home screen to add it (confirm with Add), or long-press the home screen, choose Widgets, find SignalDeck and drag the Radio widget out. It can be resized. It shows the channel number and name and the same status line, with previous, scan, next and Talk buttons. Tap the channel to open the app."),
            s("Talk from the widget", "A widget cannot feel a held finger, so Talk works tap to start, tap to stop: the button turns red while you transmit. Transmitting stops by itself at the transmit limit (Device \u2192 Longest transmission, 2 minutes unless you change it). Receive-only channels refuse it."),
            s("When the radio is off", "The buttons need the app to own the radio. If it does not, they say so; tap the channel to open the app.")),

        new Topic("Good to know", "alert", Neo.RED, "Emergency and roger beep", "Send your position; an end-of-talk tone.",
            s("Emergency", "Intercom menu \u2192 Emergency, or Device \u2192 Emergency. It sends on the channel you are on. On a DMR channel: a text 'EMERGENCY <message> @ latitude,longitude +-accuracy' to the contact or talkgroup you choose in the sheet (it is remembered). On an analog channel: an APRS position with the emergency symbol and 'EMERGENCY <message>' as the comment, or an EMERGENCY status report when the phone has no position fix; this needs your callsign in PKT \u2192 APRS settings."),
            s("Hold to send", "The red key must be held for two seconds, so a stray tap never sends. Lifting early cancels. Afterwards the sheet says what was sent; hold again to repeat it."),
            s("Pick the right channel", "Switch to the channel where someone will hear you first: your repeater or talkgroup for DMR, the local APRS frequency (Device \u2192 Region shows yours) for APRS. Only use it for a real emergency."),
            s("Roger beep", "Device \u2192 Roger beep: Off, Beep, Two-tone or Morse K. The tone is sent when you release the talk key, just before the carrier drops, so listeners know you are done. Tapping the row plays the new tone on the phone speaker.")),

        new Topic("Good to know", "alert", Neo.AMBER, "Transmitting legally", "Licences, power and the time limit.",
            s("Licences", "You are responsible for the frequencies you use: amateur bands need an amateur licence, GMRS needs a licence in the US, FRS limits power, the licence-free services differ by country (Add a zone marks those your region does not list as \"not legal here\"; Device \u2192 Region), and NOAA weather, marine and railroad channels are receive-only (the app never transmits there). The standard lists in Add a zone say on each one whether a licence is needed."),
            s("Time limit", "Device \u2192 Longest transmission sets how long one transmission may run: 30 seconds, 1, 2 (the default), 3, 5 or 10 minutes, a custom length (10 seconds or more), or No limit. It applies to everything that transmits: the talk key and the side PTT, the car, the widget, SignalDeck Web, M17, and data such as SSTV, APRS, FT8 and pages. A voice key ends when it reaches the limit (release and key again to continue); data longer than the limit is not sent, and the history says why. The radio's own timer is set a little longer (2 seconds, at most 255 seconds; off for No limit or more than 255 seconds), so SignalDeck always ends the key first. With No limit, or a limit over 255 seconds, the radio does not stop the transmission by itself: only you (release the key) or SignalDeck (its limit or the heat guard) end it, so if SignalDeck were closed or stopped working during a key, the radio would keep transmitting until you end it, for example by restarting the phone. A few modes keep their own shorter limits (the parrot 26 s, voice keyer slots 25 s, pages 25 s, text modes about 26 s per transmission). Choosing more than 2 minutes or No limit shows a heat warning once. Whatever the limit, the heat guard stays on for every key longer than 30 seconds: a voice or M17 key ends at 30 seconds, and long data such as an SSTV picture does not start, while the phone is still cooling down after the last long one (within 1 \u00B0C of where it was, or 17 minutes when the temperature cannot be read) or while the radio area is at 60 \u00B0C or the battery at 45 \u00B0C, and any long key ends early when the radio area passes 70 \u00B0C, the battery 48 \u00B0C, or either climbs 2 \u00B0C in ten seconds. The history says which. In Restricted mode the setting is locked.")),
    };

    private final Runnable onClose;
    private final FrameLayout stage;
    private LinearLayout home, homeGrid, results;
    private EditText search;
    private int current = -1;

    public HelpView(Context c, Runnable onClose) {
        super(c);
        this.onClose = onClose;
        setOrientation(VERTICAL); setBackground(Neo.page(c));
        stage = new FrameLayout(c);
        addView(stage, new LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT));
        showHome();
    }

    /** Back key: topic → home → close. Returns true when handled here. */
    public boolean back() { if (current >= 0) { showHome(); return true; } return false; }

    // ---- home ----
    private void showHome() {
        final Context c = getContext(); final float d = Theme.dp(c);
        current = -1;
        stage.removeAllViews();
        LinearLayout page = new LinearLayout(c); page.setOrientation(VERTICAL);
        LinearLayout header = Neo.header(c, "Help & how-to", TOPICS.length + " topics");
        ImageView close = Neo.iconButton(c, "close", Neo.CYAN, "Close help"); close.setOnClickListener(v -> onClose.run());
        Neo.addAction(header, close);
        page.addView(header);

        ScrollView sv = new ScrollView(c); sv.setVerticalScrollBarEnabled(false);
        home = new LinearLayout(c); home.setOrientation(VERTICAL); home.setPadding((int) (16 * d), (int) (12 * d), (int) (16 * d), (int) (28 * d));
        sv.addView(home);
        page.addView(sv, new LayoutParams(LayoutParams.MATCH_PARENT, 0, 1f));

        // search
        LinearLayout sf = new LinearLayout(c); sf.setGravity(Gravity.CENTER_VERTICAL);
        sf.setBackground(Neo.card(c, Neo.alpha(Neo.CYAN, 0x33), 12)); sf.setPadding((int) (14 * d), 0, (int) (10 * d), 0);
        ImageView si = new ImageView(c); si.setImageDrawable(new Neo.IconDrawable("search", Neo.MUTED));
        sf.addView(si, new LayoutParams((int) (18 * d), (int) (18 * d)));
        search = new EditText(c); search.setHint("Search the guide"); search.setSingleLine(true); search.setTextSize(16); search.setTypeface(Neo.uiSemi(c));
        search.setTextColor(Neo.TEXT); search.setHintTextColor(Neo.DIM); search.setBackground(null); search.setPadding((int) (10 * d), 0, 0, 0);
        search.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);
        sf.addView(search, new LayoutParams(0, (int) (44 * d), 1f));
        home.addView(sf, new LayoutParams(LayoutParams.MATCH_PARENT, (int) (46 * d)));

        results = new LinearLayout(c); results.setOrientation(VERTICAL); results.setVisibility(GONE);
        home.addView(results);
        homeGrid = new LinearLayout(c); homeGrid.setOrientation(VERTICAL);
        home.addView(homeGrid);
        search.addTextChangedListener(new TextWatcher() {
            @Override public void beforeTextChanged(CharSequence s, int a, int b, int n) { } @Override public void onTextChanged(CharSequence s, int a, int b, int n) { }
            @Override public void afterTextChanged(Editable e) { runSearch(e.toString()); }
        });

        // start here: featured card
        final Topic start = TOPICS[0];
        LinearLayout hero = new LinearLayout(c); hero.setOrientation(VERTICAL); hero.setPadding((int) (16 * d), (int) (16 * d), (int) (16 * d), (int) (16 * d));
        android.graphics.drawable.StateListDrawable hs = new android.graphics.drawable.StateListDrawable();
        hs.addState(new int[] { android.R.attr.state_pressed }, Neo.tint(c, Neo.CYAN, 18, 1.5f)); hs.addState(new int[] { }, Neo.tint(c, Neo.CYAN, 18, 1));
        hero.setBackground(hs); hero.setClickable(true); hero.setFocusable(true);
        LinearLayout ht = new LinearLayout(c); ht.setGravity(Gravity.CENTER_VERTICAL);
        ht.addView(Neo.iconTile(c, start.icon, Neo.CYAN, 52), new LayoutParams((int) (52 * d), (int) (52 * d)));
        LinearLayout hc = new LinearLayout(c); hc.setOrientation(VERTICAL); hc.setPadding((int) (14 * d), 0, 0, 0);
        TextView kicker = Neo.caps(c, "Start here"); kicker.setTextColor(Neo.CYAN_LIGHT); hc.addView(kicker);
        TextView htitle = Neo.text(c, start.title, Neo.TEXT, 21, Neo.ui(c)); htitle.setPadding(0, (int) (3 * d), 0, 0); hc.addView(htitle);
        ht.addView(hc, new LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f));
        ImageView arrow = new ImageView(c); arrow.setImageDrawable(new Neo.IconDrawable("right", Neo.CYAN)); ht.addView(arrow, new LayoutParams((int) (22 * d), (int) (22 * d)));
        hero.addView(ht);
        for (int i = 0; i < start.sections.length; i++) {
            LinearLayout step = new LinearLayout(c); step.setGravity(Gravity.CENTER_VERTICAL); step.setPadding(0, (int) (i == 0 ? 14 * d : 8 * d), 0, 0);
            TextView num = Neo.text(c, String.valueOf(i + 1), Neo.CYAN, 14, Neo.display(c)); num.setGravity(Gravity.CENTER);
            android.graphics.drawable.GradientDrawable ng = new android.graphics.drawable.GradientDrawable(); ng.setShape(android.graphics.drawable.GradientDrawable.OVAL); ng.setStroke((int) (1.5f * d), Neo.CYAN); num.setBackground(ng);
            step.addView(num, new LayoutParams((int) (26 * d), (int) (26 * d)));
            TextView st = Neo.text(c, start.sections[i].head.replaceFirst("^\\d+\\s+", ""), Neo.TEXT_SOFT, 15.5f, Neo.uiSemi(c)); st.setPadding((int) (10 * d), 0, 0, 0);
            step.addView(st);
            hero.addView(step);
        }
        hero.setOnClickListener(v -> showTopic(0, -1));
        LayoutParams hl = new LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT); hl.topMargin = (int) (14 * d);
        homeGrid.addView(hero, hl);

        // featured: the newest major feature
        int fi = -1; for (int i = 0; i < TOPICS.length; i++) if ("Coverage maps".equals(TOPICS[i].title)) fi = i;
        if (fi > 0) {
            final int fIdx = fi; Topic ft = TOPICS[fi];
            LinearLayout feat = new LinearLayout(c); feat.setOrientation(VERTICAL); feat.setPadding((int) (16 * d), (int) (14 * d), (int) (16 * d), (int) (14 * d));
            android.graphics.drawable.StateListDrawable fs = new android.graphics.drawable.StateListDrawable();
            fs.addState(new int[] { android.R.attr.state_pressed }, Neo.tint(c, Neo.VIOLET, 18, 1.5f)); fs.addState(new int[] { }, Neo.tint(c, Neo.VIOLET, 18, 1));
            feat.setBackground(fs); feat.setClickable(true); feat.setFocusable(true);
            LinearLayout fr = new LinearLayout(c); fr.setGravity(Gravity.CENTER_VERTICAL);
            fr.addView(Neo.iconTile(c, ft.icon, Neo.VIOLET, 46), new LayoutParams((int) (46 * d), (int) (46 * d)));
            LinearLayout fc = new LinearLayout(c); fc.setOrientation(VERTICAL); fc.setPadding((int) (14 * d), 0, 0, 0);
            TextView fk = Neo.caps(c, "New \u00b7 featured"); fk.setTextColor(Neo.VIOLET_LIGHT); fc.addView(fk);
            TextView ftt = Neo.text(c, ft.title, Neo.TEXT, 20, Neo.ui(c)); ftt.setPadding(0, (int) (3 * d), 0, 0); fc.addView(ftt);
            fr.addView(fc, new LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f));
            ImageView fa = new ImageView(c); fa.setImageDrawable(new Neo.IconDrawable("right", Neo.VIOLET)); fr.addView(fa, new LayoutParams((int) (22 * d), (int) (22 * d)));
            feat.addView(fr);
            TextView fsum = Neo.text(c, "See where each repeater reaches you and where you can key it up, measured automatically as you drive or walk. Two map layers, export to Google Earth.", Neo.TEXT_SOFT, 14.5f, Neo.uiMedium(c));
            fsum.setPadding(0, (int) (10 * d), 0, 0); fsum.setLineSpacing(0, 1.1f); feat.addView(fsum);
            feat.setOnClickListener(v -> showTopic(fIdx, -1));
            LayoutParams fl = new LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT); fl.topMargin = (int) (12 * d);
            homeGrid.addView(feat, fl);
        }

        // topic tiles by group
        String group = null; LinearLayout rowOpen = null;
        for (int i = 1; i < TOPICS.length; i++) {
            final int idx = i; Topic t = TOPICS[i];
            if (!t.group.equals(group)) {
                group = t.group; rowOpen = null;
                TextView gh = Neo.caps(c, group); gh.setPadding((int) (2 * d), (int) (22 * d), 0, (int) (8 * d)); homeGrid.addView(gh);
            }
            LinearLayout tile = Neo.tile(c, t.icon, t.accent, t.title, t.summary);
            tile.setOnClickListener(v -> showTopic(idx, -1));
            if (rowOpen == null) {
                rowOpen = new LinearLayout(c); rowOpen.setBaselineAligned(false);
                LayoutParams l1 = new LayoutParams(0, LayoutParams.MATCH_PARENT, 1f); l1.setMargins(0, 0, (int) (4 * d), (int) (8 * d));
                rowOpen.addView(tile, l1);
                // a lone tile still takes half the row
                View spacer = new View(c); spacer.setTag("spacer");
                LayoutParams l2 = new LayoutParams(0, LayoutParams.MATCH_PARENT, 1f); l2.setMargins((int) (4 * d), 0, 0, (int) (8 * d));
                rowOpen.addView(spacer, l2);
                homeGrid.addView(rowOpen);
            } else {
                View spacer = rowOpen.findViewWithTag("spacer"); LayoutParams l2 = (LayoutParams) spacer.getLayoutParams();
                rowOpen.removeView(spacer); rowOpen.addView(tile, l2);
                rowOpen = null;
            }
        }
        stage.addView(page);
    }

    private void runSearch(String q) {
        final Context c = getContext(); final float d = Theme.dp(c);
        q = q.trim().toLowerCase(Locale.US);
        results.removeAllViews();
        if (q.isEmpty()) { results.setVisibility(GONE); homeGrid.setVisibility(VISIBLE); return; }
        homeGrid.setVisibility(GONE); results.setVisibility(VISIBLE);
        int n = 0;
        for (int i = 0; i < TOPICS.length; i++) {
            Topic t = TOPICS[i];
            for (int k = 0; k < t.sections.length; k++) {
                Section sec = t.sections[k];
                String body = sec.text.toLowerCase(Locale.US);
                boolean hit = sec.head.toLowerCase(Locale.US).contains(q) || body.contains(q) || (k == 0 && t.title.toLowerCase(Locale.US).contains(q));
                if (!hit) continue;
                final int ti = i, sk = k;
                LinearLayout card = new LinearLayout(c); card.setOrientation(VERTICAL); card.setPadding((int) (14 * d), (int) (12 * d), (int) (14 * d), (int) (12 * d));
                card.setBackground(Neo.card(c, Neo.alpha(t.accent, 0x55), 14)); card.setClickable(true);
                LinearLayout top = new LinearLayout(c); top.setGravity(Gravity.CENTER_VERTICAL);
                ImageView ic = new ImageView(c); ic.setImageDrawable(new Neo.IconDrawable(t.icon, t.accent)); top.addView(ic, new LayoutParams((int) (18 * d), (int) (18 * d)));
                TextView tt = Neo.caps(c, t.title + "  ·  " + sec.head.replaceFirst("^\\d+\\s+", "")); tt.setTextColor(Neo.alpha(t.accent, 0xFF)); tt.setPadding((int) (8 * d), 0, 0, 0); top.addView(tt);
                card.addView(top);
                int at = body.indexOf(q); int from = Math.max(0, at - 50);
                String snip = at < 0 ? sec.text : (from > 0 ? "…" : "") + sec.text.substring(from, Math.min(sec.text.length(), at + 110)) + (at + 110 < sec.text.length() ? "…" : "");
                TextView sn = Neo.text(c, snip, Neo.TEXT_SOFT, 14, Neo.uiMedium(c)); sn.setPadding(0, (int) (6 * d), 0, 0); sn.setLineSpacing(0, 1.1f);
                card.addView(sn);
                card.setOnClickListener(v -> showTopic(ti, sk));
                LayoutParams lp = new LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT); lp.topMargin = (int) (10 * d);
                results.addView(card, lp);
                n++;
            }
        }
        if (n == 0) {
            TextView none = Neo.text(c, "Nothing in the guide matches “" + q + "”.", Neo.MUTED, 15, Neo.uiMedium(c)); none.setPadding((int) (4 * d), (int) (20 * d), 0, 0);
            results.addView(none);
        }
    }

    // ---- topic page ----
    private void showTopic(final int idx, final int focusSection) {
        final Context c = getContext(); final float d = Theme.dp(c);
        current = idx;
        final Topic t = TOPICS[idx];
        stage.removeAllViews();
        LinearLayout page = new LinearLayout(c); page.setOrientation(VERTICAL);
        LinearLayout header = Neo.header(c, t.title, t.group + "  ·  " + (idx + 1) + " of " + TOPICS.length);
        ImageView back = Neo.iconButton(c, "left", Neo.CYAN, "All topics"); back.setOnClickListener(v -> showHome());
        LayoutParams bl = new LayoutParams((int) (44 * d), (int) (44 * d)); bl.rightMargin = (int) (12 * d);
        header.addView(back, 0, bl);
        ImageView close = Neo.iconButton(c, "close", Neo.CYAN, "Close help"); close.setOnClickListener(v -> onClose.run());
        Neo.addAction(header, close);
        page.addView(header);

        final ScrollView sv = new ScrollView(c); sv.setVerticalScrollBarEnabled(false);
        LinearLayout body = new LinearLayout(c); body.setOrientation(VERTICAL); body.setPadding((int) (16 * d), (int) (14 * d), (int) (16 * d), (int) (28 * d));
        sv.addView(body);
        page.addView(sv, new LayoutParams(LayoutParams.MATCH_PARENT, 0, 1f));

        LinearLayout lead = new LinearLayout(c); lead.setGravity(Gravity.CENTER_VERTICAL);
        lead.addView(Neo.iconTile(c, t.icon, t.accent, 56), new LayoutParams((int) (56 * d), (int) (56 * d)));
        TextView sum = Neo.text(c, t.summary, Neo.TEXT, 18, Neo.ui(c)); sum.setPadding((int) (14 * d), 0, 0, 0); sum.setLineSpacing(0, 1.05f);
        lead.addView(sum, new LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f));
        body.addView(lead);

        final View[] secViews = new View[t.sections.length];
        for (int k = 0; k < t.sections.length; k++) {
            Section sec = t.sections[k];
            LinearLayout card = new LinearLayout(c); card.setOrientation(VERTICAL); card.setPadding((int) (16 * d), (int) (14 * d), (int) (16 * d), (int) (16 * d));
            card.setBackground(Neo.card(c, k == focusSection ? t.accent : Neo.LINE, 16));
            LinearLayout hrow = new LinearLayout(c); hrow.setGravity(Gravity.CENTER_VERTICAL);
            View bar = new View(c); android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable(); bg.setColor(t.accent); bg.setCornerRadius(2 * d); bar.setBackground(bg);
            hrow.addView(bar, new LayoutParams((int) (3 * d), (int) (16 * d)));
            TextView h = Neo.text(c, sec.head, Neo.TEXT, 16.5f, Neo.ui(c)); h.setPadding((int) (10 * d), 0, 0, 0); hrow.addView(h);
            card.addView(hrow);
            TextView tx = Neo.text(c, sec.text, Neo.TEXT_SOFT, 15, Neo.uiMedium(c)); tx.setLineSpacing(0, 1.18f); tx.setPadding(0, (int) (8 * d), 0, 0);
            tx.setTextIsSelectable(false);
            card.addView(tx);
            LayoutParams lp = new LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT); lp.topMargin = (int) (12 * d);
            body.addView(card, lp);
            secViews[k] = card;
        }

        // previous / next
        LinearLayout nav = new LinearLayout(c); nav.setBaselineAligned(false);
        LayoutParams nl = new LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT); nl.topMargin = (int) (20 * d);
        if (idx > 0) {
            View prev = navCard(c, "Previous", TOPICS[idx - 1], false); prev.setOnClickListener(v -> showTopic(idx - 1, -1));
            LayoutParams p = new LayoutParams(0, LayoutParams.MATCH_PARENT, 1f); p.rightMargin = (int) (4 * d); nav.addView(prev, p);
        }
        if (idx < TOPICS.length - 1) {
            View next = navCard(c, "Next", TOPICS[idx + 1], true); next.setOnClickListener(v -> showTopic(idx + 1, -1));
            LayoutParams p = new LayoutParams(0, LayoutParams.MATCH_PARENT, 1f); p.leftMargin = idx > 0 ? (int) (4 * d) : 0; nav.addView(next, p);
        }
        body.addView(nav, nl);
        TextView all = Neo.button(c, "All topics", "menu", Neo.CYAN); all.setOnClickListener(v -> showHome());
        LayoutParams al = new LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT); al.topMargin = (int) (10 * d);
        body.addView(all, al);

        stage.addView(page);
        if (focusSection >= 0) sv.post(() -> sv.smoothScrollTo(0, Math.max(0, secViews[focusSection].getTop() - (int) (8 * d))));
    }

    private static View navCard(Context c, String label, Topic t, boolean next) {
        float d = Theme.dp(c);
        LinearLayout card = new LinearLayout(c); card.setOrientation(VERTICAL); card.setGravity(next ? Gravity.END : Gravity.START);
        card.setPadding((int) (14 * d), (int) (12 * d), (int) (14 * d), (int) (12 * d));
        android.graphics.drawable.StateListDrawable s = new android.graphics.drawable.StateListDrawable();
        s.addState(new int[] { android.R.attr.state_pressed }, Neo.tint(c, t.accent, 14, 1.5f)); s.addState(new int[] { }, Neo.card(c, Neo.alpha(t.accent, 0x66), 14));
        card.setBackground(s); card.setClickable(true); card.setFocusable(true);
        TextView l = Neo.caps(c, (next ? "" : "← ") + label + (next ? " →" : "")); card.addView(l);
        TextView tt = Neo.text(c, t.title, Neo.TEXT, 16, Neo.ui(c)); tt.setPadding(0, (int) (4 * d), 0, 0); tt.setGravity(next ? Gravity.END : Gravity.START); card.addView(tt);
        return card;
    }
}
